window.QBANK = window.QBANK || {};
window.QBANK["sma-sosiologi"] = {
  level: "SMA", subject: "Sosiologi", duration: 900,
  questions: [
    { q: "Syarat terjadinya interaksi sosial adalah adanya ....", options: ["kontak sosial dan komunikasi", "konflik dan persaingan", "norma sosial dan sanksi", "status sosial dan peran sosial"], answer: 0, solution: "1. Interaksi sosial adalah hubungan timbal balik antara individu dengan individu, individu dengan kelompok, atau kelompok dengan kelompok. 2. Menurut para sosiolog, interaksi sosial baru terjadi jika memenuhi dua syarat, yaitu kontak sosial dan komunikasi. 3. Kontak sosial dapat berupa tatap muka langsung maupun melalui media, sedangkan komunikasi adalah penyampaian pesan yang mengandung makna dan dipahami pihak lain." },
    { q: "Dua penumpang yang tidak saling kenal duduk berdampingan di dalam bus tanpa saling menyapa. Kondisi tersebut ....", options: ["sudah termasuk interaksi sosial karena ada kontak fisik", "hanya memenuhi syarat kontak sosial, belum terjadi interaksi", "sudah memenuhi syarat komunikasi nonverbal", "termasuk bentuk kerja sama dalam interaksi sosial"], answer: 1, solution: "1. Kontak sosial adalah hubungan yang terjadi melalui tatap muka atau perantara, misalnya duduk berdampingan di bus. 2. Komunikasi adalah penyampaian pesan yang bermakna dan dipahami oleh penerima pesan. 3. Karena kedua penumpang tidak saling menyapa (tidak ada pesan yang disampaikan dan dipahami), yang ada hanyalah kontak sosial, sehingga interaksi sosial belum terjadi." },
    { q: "Berikut ini pasangan bentuk interaksi sosial yang keduanya bersifat asosiatif adalah ....", options: ["persaingan dan pertentangan", "konflik dan kontravensi", "kerja sama dan akomodasi", "persaingan dan kerja sama"], answer: 2, solution: "1. Bentuk interaksi sosial dibedakan menjadi asosiatif (mengarah pada persatuan) dan disosiatif (mengarah pada perpecahan). 2. Bentuk asosiatif meliputi kerja sama, akomodasi, asimilasi, dan akulturasi. 3. Persaingan, kontravensi, pertentangan, dan konflik bersifat disosiatif, sehingga pasangan yang keduanya asosiatif adalah kerja sama dan akomodasi." },
    { q: "Seorang remaja meniru gaya berpakaian idolanya hingga ingin berpenampilan persis seperti sang idola dalam kehidupan sehari-hari. Gejala sosial tersebut disebut ....", options: ["imitasi", "sugesti", "simpati", "identifikasi"], answer: 3, solution: "1. Imitasi adalah meniru perilaku orang lain, sedangkan identifikasi adalah meniru secara menyeluruh hingga ingin menjadi persis seperti yang ditiru. 2. Pada kasus ini remaja tidak sekadar meniru, melainkan ingin menjadi persis seperti idolanya dalam kehidupan sehari-hari. 3. Oleh karena itu proses yang terjadi adalah identifikasi, bukan sekadar imitasi." },
    { q: "Seseorang mengikuti ajakan temannya membeli barang tertentu tanpa memikirkan kembali baik-buruknya ajakan itu. Proses interaksi sosial yang terjadi adalah ....", options: ["sugesti", "imitasi", "empati", "motivasi"], answer: 0, solution: "1. Sugesti adalah pengaruh yang diterima seseorang tanpa berpikir kritis terlebih dahulu. 2. Pada kasus ini orang tersebut langsung mengikuti ajakan tanpa mempertimbangkan baik-buruknya, yang menunjukkan ia menerima pengaruh tanpa daya kritis. 3. Hal ini berbeda dengan imitasi (meniru perilaku) dan empati (ikut merasakan perasaan orang lain), sehingga jawabannya adalah sugesti." },
    { q: "Andi ikut menangis ketika melihat sahabatnya menangis karena ia merasakan kesedihan yang sama. Sikap Andi tersebut disebut ....", options: ["simpati", "empati", "sugesti", "imitasi"], answer: 1, solution: "1. Simpati adalah ketertarikan atau rasa tergerak hati terhadap orang lain, sedangkan empati adalah ikut merasakan perasaan yang dialami orang lain. 2. Andi tidak hanya tertarik atau tergerak hatinya, tetapi benar-benar merasakan kesedihan yang sama hingga ikut menangis. 3. Karena ia ikut merasakan perasaan sahabatnya, sikap tersebut disebut empati." },
    { q: "Seorang guru memberi dorongan semangat kepada muridnya agar berani tampil di depan kelas. Dorongan tersebut dalam proses interaksi sosial disebut ....", options: ["sugesti", "identifikasi", "motivasi", "simpati"], answer: 2, solution: "1. Motivasi adalah dorongan yang diberikan seseorang kepada orang lain agar melakukan sesuatu atau mencapai tujuan tertentu. 2. Dorongan semangat dari guru bertujuan agar murid berani tampil, artinya guru memberikan rangsangan agar murid bertindak. 3. Hal ini berbeda dengan sugesti yang diterima tanpa daya kritis, sehingga dorongan yang disadari tujuannya ini disebut motivasi." },
    { q: "Ciri utama yang membedakan kelompok sosial dari sekadar kerumunan (crowd) adalah ....", options: ["jumlah anggotanya sangat banyak", "berada di tempat yang sama dalam waktu lama", "dipimpin oleh seorang pemimpin", "adanya interaksi dan kesadaran akan keanggotaan"], answer: 3, solution: "1. Menurut Soerjono Soekanto, kelompok sosial memiliki syarat: setiap anggota sadar sebagai bagian kelompok, ada hubungan timbal balik, dan ada faktor pengikat. 2. Kerumunan hanya berkumpul di tempat yang sama tanpa interaksi yang terorganisasi dan tanpa kesadaran keanggotaan. 3. Oleh karena itu pembedanya adalah adanya interaksi timbal balik dan kesadaran setiap anggota akan keanggotaannya." },
    { q: "Menurut Charles Horton Cooley, kelompok yang hubungan antaranggotanya bersifat pribadi, akrab, dan berlangsung lama, seperti keluarga, disebut kelompok ....", options: ["primer", "sekunder", "formal", "referensi"], answer: 0, solution: "1. Cooley membedakan kelompok menjadi primer dan sekunder berdasarkan kualitas hubungan antaranggota. 2. Kelompok primer bercirikan hubungan yang bersifat pribadi, akrab, intim, dan berlangsung relatif lama, contohnya keluarga dan kelompok bermain. 3. Kelompok sekunder sebaliknya bersifat formal dan impersonal, sehingga keluarga termasuk kelompok primer." },
    { q: "Warga sebuah RT saling mengenal akrab dan tolong-menolong atas dasar kekeluargaan. Bentuk kelompok sosial tersebut adalah ....", options: ["patembayan", "paguyuban", "kelompok sekunder", "out-group"], answer: 1, solution: "1. Menurut Ferdinand Tonnies, paguyuban (gemeinschaft) adalah kelompok yang hubungan antaranggotanya bersifat pribadi, akrab, dan didasari rasa kekeluargaan. 2. Patembayan (gesellschaft) sebaliknya bersifat formal dan didasari kepentingan tertentu. 3. Karena warga RT berhubungan atas dasar kekeluargaan dan keakraban, kelompok ini termasuk paguyuban." },
    { q: "Para karyawan sebuah perusahaan bekerja sama semata-mata untuk mencapai target penjualan dan hubungan mereka bersifat formal. Bentuk kelompok tersebut adalah ....", options: ["paguyuban", "kelompok primer", "patembayan", "in-group"], answer: 2, solution: "1. Patembayan (gesellschaft) menurut Tonnies adalah kelompok yang anggotanya berhubungan secara formal dan impersonal demi mencapai kepentingan atau tujuan tertentu. 2. Hubungan karyawan perusahaan hanya terjalin untuk mencapai target penjualan, bukan karena keakraban pribadi. 3. Oleh karena itu kelompok ini termasuk patembayan, bukan paguyuban yang didasari kekeluargaan." },
    { q: "Siswa kelas XII IPA 1 merasa kelasnya paling unggul dan memandang rendah kelas-kelas lain. Sikap tersebut menunjukkan adanya ....", options: ["membership group dan reference group", "kelompok primer dan sekunder", "paguyuban dan patembayan", "in-group dan out-group"], answer: 3, solution: "1. Menurut William Graham Sumner, in-group adalah kelompok tempat seseorang merasa menjadi anggota, sedangkan out-group adalah kelompok di luar keanggotaannya. 2. Siswa tersebut membanggakan kelasnya sendiri (in-group) sekaligus merendahkan kelas lain (out-group). 3. Sikap membeda-bedakan kami versus mereka inilah yang menunjukkan adanya in-group dan out-group." },
    { q: "Rina belum menjadi anggota OSIS, tetapi ia selalu meniru gaya dan menaati aturan OSIS karena mengidolakan organisasi itu. Kedudukan OSIS bagi Rina adalah sebagai ....", options: ["reference group", "membership group", "in-group", "kelompok primer"], answer: 0, solution: "1. Menurut Robert K. Merton, membership group adalah kelompok tempat seseorang menjadi anggota, sedangkan reference group adalah kelompok yang dijadikan acuan atau pedoman berperilaku meskipun bukan anggotanya. 2. Rina belum menjadi anggota OSIS, tetapi menjadikan OSIS sebagai acuan gaya dan perilakunya. 3. Oleh karena itu OSIS bagi Rina adalah reference group, bukan membership group." },
    { q: "Hubungan antara dokter dan pasien di rumah sakit pada umumnya bersifat ....", options: ["pribadi dan akrab seperti hubungan keluarga", "formal dan berorientasi pada kepentingan tertentu", "didasari ikatan batin yang mendalam", "akrab, intim, dan berlangsung seumur hidup"], answer: 1, solution: "1. Kelompok sekunder menurut Cooley bercirikan hubungan yang formal, impersonal, dan berorientasi pada tujuan atau kepentingan tertentu. 2. Hubungan dokter dan pasien terjalin untuk kepentingan pengobatan, bersifat profesional dan tidak didasari keakraban pribadi. 3. Oleh karena itu hubungan tersebut termasuk kelompok sekunder, bukan kelompok primer seperti keluarga." },
    { q: "Sistem pelapisan masyarakat secara vertikal ke dalam kelas-kelas yang menunjukkan adanya tingkatan disebut ....", options: ["diferensiasi sosial", "mobilitas sosial", "stratifikasi sosial", "integrasi sosial"], answer: 2, solution: "1. Stratifikasi sosial adalah pembedaan masyarakat ke dalam lapisan-lapisan secara vertikal atau bertingkat. 2. Pelapisan ini menunjukkan adanya tingkatan, misalnya kelas atas, menengah, dan bawah berdasarkan kekayaan, kekuasaan, atau kehormatan. 3. Hal ini berbeda dengan diferensiasi sosial yang bersifat horizontal dan tidak menunjukkan tingkatan." },
    { q: "Perbedaan suku bangsa, agama, dan jenis kelamin dalam masyarakat merupakan contoh ....", options: ["stratifikasi sosial", "mobilitas vertikal", "konflik sosial", "diferensiasi sosial"], answer: 3, solution: "1. Diferensiasi sosial adalah pembedaan masyarakat secara horizontal berdasarkan ciri-ciri tertentu tanpa menunjukkan adanya tingkatan. 2. Suku bangsa, agama, dan jenis kelamin membedakan masyarakat tetapi tidak ada yang lebih tinggi atau lebih rendah. 3. Oleh karena itu ketiganya termasuk diferensiasi sosial, bukan stratifikasi sosial yang bersifat vertikal dan berjenjang." },
    { q: "Perbedaan mendasar antara stratifikasi sosial dan diferensiasi sosial terletak pada ....", options: ["ada atau tidaknya tingkatan dalam pembedaan masyarakat", "banyaknya jumlah anggota masyarakat", "ada atau tidaknya interaksi sosial", "tingkat pendidikan anggota masyarakat"], answer: 0, solution: "1. Stratifikasi sosial membedakan masyarakat secara vertikal sehingga menunjukkan adanya tingkatan atau hierarki. 2. Diferensiasi sosial membedakan masyarakat secara horizontal, misalnya berdasarkan suku, agama, dan jenis kelamin, tanpa tingkatan. 3. Jadi perbedaan mendasarnya adalah ada atau tidaknya tingkatan dalam pembedaan masyarakat tersebut." },
    { q: "Penggolongan masyarakat menjadi kelas atas, kelas menengah, dan kelas bawah didasarkan pada kriteria ....", options: ["kekuasaan politik", "kekayaan", "kehormatan", "ilmu pengetahuan"], answer: 1, solution: "1. Menurut Pitirim Sorokin, stratifikasi sosial dapat didasarkan pada kriteria ekonomi (kekayaan), politik (kekuasaan), dan sosial (kehormatan). 2. Penggolongan menjadi kelas atas, menengah, dan bawah menunjukkan perbedaan tingkat kepemilikan harta benda. 3. Oleh karena itu kriteria yang digunakan adalah kekayaan atau kriteria ekonomi." },
    { q: "Sistem kasta di India dan sistem feodal di Eropa pada abad pertengahan termasuk stratifikasi sosial yang bersifat ....", options: ["terbuka", "campuran", "tertutup", "demokratis"], answer: 2, solution: "1. Stratifikasi tertutup adalah sistem pelapisan yang tidak memungkinkan anggotanya berpindah lapisan, misalnya sistem kasta dan sistem feodal. 2. Dalam sistem kasta, status seseorang ditentukan sejak lahir dan tidak dapat berubah seumur hidup. 3. Karena tidak ada peluang mobilitas antarlapisan, sistem ini termasuk stratifikasi tertutup." },
    { q: "Perbedaan profesi antara dokter, guru, dan petani menunjukkan adanya ....", options: ["stratifikasi sosial karena profesi menunjukkan tingkatan", "mobilitas sosial karena profesi dapat berubah", "konflik sosial karena profesi menimbulkan persaingan", "diferensiasi sosial karena profesi merupakan penggolongan horizontal"], answer: 3, solution: "1. Diferensiasi sosial adalah penggolongan masyarakat secara horizontal yang tidak menunjukkan tingkatan, salah satunya berdasarkan profesi. 2. Dokter, guru, dan petani memang berbeda jenis pekerjaannya, tetapi perbedaan itu tidak mutlak menunjukkan siapa lebih tinggi atau lebih rendah. 3. Oleh karena itu perbedaan profesi termasuk diferensiasi sosial, bukan stratifikasi sosial." },
    { q: "Seorang anak tukang becak berhasil menjadi seorang pengacara terkenal. Perpindahan status sosial tersebut termasuk mobilitas ....", options: ["vertikal naik (social climbing)", "vertikal turun (social sinking)", "horizontal", "geografis"], answer: 0, solution: "1. Mobilitas vertikal adalah perpindahan status sosial yang mengubah tingkatan atau derajat seseorang. 2. Anak tukang becak yang menjadi pengacara mengalami kenaikan status sosial ke lapisan yang lebih tinggi. 3. Kenaikan status sosial seperti ini disebut mobilitas vertikal naik atau social climbing." },
    { q: "Seorang guru pindah mengajar dari satu sekolah ke sekolah lain dengan jabatan dan gaji yang setara. Perpindahan tersebut termasuk mobilitas ....", options: ["vertikal naik", "horizontal", "vertikal turun", "antargenerasi"], answer: 1, solution: "1. Mobilitas horizontal adalah perpindahan status sosial tanpa mengubah tingkatan atau derajat seseorang. 2. Guru tersebut hanya berpindah tempat kerja, sedangkan jabatan dan gajinya tetap setara, sehingga tidak ada perubahan tingkatan. 3. Oleh karena itu perpindahan ini termasuk mobilitas horizontal." },
    { q: "Seorang anak petani berhasil menjadi dokter. Jika dibandingkan dengan status orang tuanya, mobilitas sosial yang terjadi bersifat ....", options: ["intragenerasi", "horizontal", "antargenerasi naik", "vertikal turun"], answer: 2, solution: "1. Mobilitas antargenerasi adalah perpindahan status sosial yang terjadi antara dua generasi atau lebih, misalnya antara orang tua dan anak. 2. Anak petani yang menjadi dokter memiliki status lebih tinggi dibanding orang tuanya yang petani. 3. Karena perbandingan dilakukan antargenerasi dan arahnya naik, maka disebut mobilitas antargenerasi naik." },
    { q: "Seorang pengusaha yang bangkrut akhirnya harus bekerja sebagai buruh harian. Peristiwa tersebut merupakan contoh mobilitas ....", options: ["vertikal naik", "horizontal", "antargenerasi", "vertikal turun (social sinking)"], answer: 3, solution: "1. Mobilitas vertikal turun (social sinking) adalah perpindahan status sosial ke lapisan yang lebih rendah. 2. Pengusaha yang bangkrut lalu menjadi buruh harian mengalami penurunan status sosial dan ekonomi. 3. Karena arah perpindahannya turun ke lapisan yang lebih rendah, peristiwa ini disebut mobilitas vertikal turun atau social sinking." },
    { q: "Saluran mobilitas sosial yang paling umum dan efektif digunakan masyarakat untuk meningkatkan status sosial adalah melalui ....", options: ["pendidikan", "perkawinan", "organisasi militer", "badan keagamaan"], answer: 0, solution: "1. Saluran mobilitas sosial adalah sarana yang memungkinkan seseorang berpindah status, misalnya pendidikan, organisasi politik, organisasi ekonomi, dan perkawinan. 2. Pendidikan membuka akses ke pekerjaan dan penghasilan yang lebih baik sehingga menjadi jalur paling umum bagi masyarakat umum. 3. Oleh karena itu pendidikan disebut saluran mobilitas sosial yang paling umum dan efektif." },
    { q: "Seorang karyawan yang dipromosikan menjadi manajer dalam masa kariernya sendiri mengalami mobilitas ....", options: ["antargenerasi", "intragenerasi", "horizontal", "lateral"], answer: 1, solution: "1. Mobilitas intragenerasi adalah perpindahan status sosial yang dialami seseorang dalam masa hidupnya sendiri atau dalam satu generasi. 2. Karyawan yang naik menjadi manajer mengalami perubahan status dalam kariernya sendiri, bukan dibandingkan dengan orang tuanya. 3. Oleh karena itu peristiwa ini termasuk mobilitas intragenerasi." },
    { q: "Pertentangan yang disertai kekerasan atau ancaman kekerasan untuk mencapai suatu tujuan disebut ....", options: ["persaingan", "kontravensi", "konflik", "akomodasi"], answer: 2, solution: "1. Konflik sosial adalah pertentangan yang dilakukan dengan kekerasan atau ancaman kekerasan untuk mencapai tujuan. 2. Persaingan juga merupakan bentuk pertentangan, tetapi dilakukan tanpa kekerasan dan mengikuti aturan yang disepakati. 3. Karena dalam kasus ini ada unsur kekerasan atau ancaman kekerasan, maka disebut konflik, bukan persaingan." },
    { q: "Konflik antara buruh dan pemilik perusahaan pada umumnya disebabkan oleh perbedaan ....", options: ["kebudayaan", "suku bangsa", "pandangan keagamaan", "kepentingan ekonomi"], answer: 3, solution: "1. Salah satu penyebab konflik sosial menurut para sosiolog adalah perbedaan kepentingan, termasuk kepentingan ekonomi. 2. Buruh menginginkan upah yang layak, sedangkan pemilik perusahaan ingin menekan biaya produksi demi keuntungan. 3. Pertentangan dua kepentingan ekonomi inilah yang umumnya memicu konflik antara buruh dan pemilik perusahaan." },
    { q: "Penyelesaian konflik dengan cara mempertemukan pihak-pihak yang berselisih agar mereka menyelesaikan sendiri masalahnya tanpa campur tangan pihak ketiga disebut ....", options: ["konsiliasi", "mediasi", "arbitrasi", "ajudikasi"], answer: 0, solution: "1. Konsiliasi adalah upaya penyelesaian konflik dengan mempertemukan pihak yang berselisih agar berunding dan menyelesaikan sendiri permasalahannya. 2. Dalam konsiliasi tidak ada pihak ketiga yang ikut campur memberikan nasihat atau keputusan. 3. Karena pihak yang berselisih menyelesaikan sendiri tanpa pihak ketiga, cara ini disebut konsiliasi." },
    { q: "Dua pihak yang bersengketa tanah meminta bantuan tokoh masyarakat sebagai penasihat, tetapi keputusan akhir tetap berada di tangan kedua belah pihak. Cara penyelesaian tersebut disebut ....", options: ["konsiliasi", "mediasi", "arbitrasi", "ajudikasi"], answer: 1, solution: "1. Mediasi adalah penyelesaian konflik dengan bantuan pihak ketiga sebagai penasihat atau fasilitator, tanpa wewenang memutus. 2. Pada kasus ini tokoh masyarakat hanya memberi nasihat, sedangkan keputusan akhir tetap di tangan pihak yang bersengketa. 3. Karena ada pihak ketiga yang bersifat menasihati dan tidak memutus, cara ini disebut mediasi." },
    { q: "Dua perusahaan yang bersengketa sepakat menunjuk seorang ahli untuk memutuskan perkara dan kedua pihak terikat pada keputusan tersebut. Cara penyelesaian tersebut disebut ....", options: ["mediasi", "konsiliasi", "arbitrasi", "ajudikasi"], answer: 2, solution: "1. Arbitrasi adalah penyelesaian konflik dengan menunjuk pihak ketiga yang berwenang memberi keputusan, dan keputusan itu mengikat kedua belah pihak. 2. Pada kasus ini ahli yang ditunjuk diberi wewenang memutus, dan kedua perusahaan terikat pada putusannya. 3. Karena pihak ketiga memutus dan keputusannya mengikat, cara ini disebut arbitrasi, bukan mediasi yang keputusannya tidak mengikat." },
    { q: "Sengketa warisan yang tidak dapat diselesaikan secara musyawarah akhirnya dibawa ke pengadilan untuk diputus. Penyelesaian melalui pengadilan tersebut disebut ....", options: ["arbitrasi", "mediasi", "konsiliasi", "ajudikasi"], answer: 3, solution: "1. Ajudikasi adalah penyelesaian konflik melalui jalur pengadilan, di mana hakim memutus perkara berdasarkan hukum yang berlaku. 2. Pada kasus ini sengketa warisan dibawa ke pengadilan karena musyawarah tidak berhasil. 3. Karena penyelesaian dilakukan melalui lembaga peradilan, cara ini disebut ajudikasi." },
    { q: "Berikut ini yang merupakan akibat positif dari konflik sosial adalah ....", options: ["meningkatnya solidaritas dalam kelompok", "terjadinya perpecahan dalam masyarakat", "menurunnya moral anggota kelompok", "munculnya disintegrasi sosial"], answer: 0, solution: "1. Konflik tidak selalu berdampak negatif; menurut Lewis Coser, konflik dapat mempererat solidaritas anggota kelompok yang berkonflik. 2. Ancaman dari pihak luar membuat anggota kelompok menjadi lebih kompak dan bersatu menghadapi lawan. 3. Oleh karena itu meningkatnya solidaritas dalam kelompok merupakan akibat positif konflik, sedangkan perpecahan dan disintegrasi adalah akibat negatifnya." },
    { q: "Proses peleburan dua kebudayaan atau lebih sehingga kebudayaan asli melebur dan menghasilkan kebudayaan baru disebut ....", options: ["akulturasi", "asimilasi", "difusi", "amalgamasi"], answer: 1, solution: "1. Asimilasi adalah proses peleburan dua kebudayaan atau lebih sehingga kebudayaan asli lambat laun hilang dan terbentuk kebudayaan baru. 2. Akulturasi berbeda karena kebudayaan asli tidak hilang, hanya menerima unsur kebudayaan baru. 3. Karena dalam kasus ini kebudayaan asli melebur dan hilang, prosesnya disebut asimilasi." },
    { q: "Masuknya unsur kebudayaan asing ke Indonesia tanpa menghilangkan ciri khas kebudayaan Indonesia disebut ....", options: ["asimilasi", "disimilasi", "akulturasi", "amalgamasi"], answer: 2, solution: "1. Akulturasi adalah proses penerimaan unsur kebudayaan baru tanpa menghilangkan kepribadian atau ciri khas kebudayaan asli. 2. Kebudayaan Indonesia menerima unsur asing, tetapi identitas kebudayaan Indonesia tetap bertahan. 3. Karena kebudayaan asli tidak hilang, proses ini disebut akulturasi, bukan asimilasi yang justru meleburkan kebudayaan asli." },
    { q: "Sekelompok pendatang menetap di suatu daerah, lalu bahasa dan adat mereka lambat laun hilang dan melebur ke dalam kebudayaan penduduk setempat. Proses tersebut disebut ....", options: ["akulturasi", "amalgamasi", "difusi", "asimilasi"], answer: 3, solution: "1. Asimilasi terjadi ketika suatu kelompok pendatang melebur ke dalam kebudayaan kelompok setempat hingga kebudayaan aslinya hilang. 2. Pada kasus ini bahasa dan adat pendatang lambat laun hilang dan menyatu dengan kebudayaan setempat. 3. Karena kebudayaan asli pendatang melebur dan hilang, proses ini disebut asimilasi." },
    { q: "Setelah konflik antarkampung mereda, kedua pihak berdamai dan menjalin kembali hubungan sosial yang harmonis seperti semula. Proses tersebut disebut ....", options: ["reintegrasi", "integrasi", "asimilasi", "akulturasi"], answer: 0, solution: "1. Reintegrasi adalah proses penyatuan kembali unsur-unsur masyarakat yang sebelumnya terpecah akibat konflik. 2. Kedua kampung yang berkonflik akhirnya berdamai dan kembali menjalin hubungan harmonis seperti sebelum konflik. 3. Karena yang terjadi adalah pemulihan kesatuan setelah perpecahan, proses ini disebut reintegrasi, bukan integrasi yang merupakan penyatuan pertama kali." },
    { q: "Proses penyesuaian unsur-unsur yang berbeda dalam masyarakat sehingga menjadi satu kesatuan yang serasi disebut ....", options: ["disintegrasi", "integrasi", "mobilitas", "diferensiasi"], answer: 1, solution: "1. Integrasi sosial adalah proses penyesuaian unsur-unsur yang berbeda dalam masyarakat menjadi satu kesatuan yang utuh dan serasi. 2. Unsur-unsur yang berbeda, misalnya suku atau kepentingan yang beragam, disatukan melalui nilai dan norma bersama. 3. Oleh karena itu proses penyatuan unsur yang berbeda menjadi kesatuan yang serasi disebut integrasi sosial." },
    { q: "Contoh akulturasi dalam bidang arsitektur adalah ....", options: ["hilangnya bahasa daerah karena semua orang berbahasa Indonesia", "terjadinya perkawinan campur antarsuku bangsa", "masjid yang memadukan arsitektur Timur Tengah dan Jawa", "terbentuknya bahasa kreol di daerah pelabuhan"], answer: 2, solution: "1. Akulturasi adalah penerimaan unsur kebudayaan baru tanpa menghilangkan ciri khas kebudayaan asli. 2. Masjid yang memadukan arsitektur Timur Tengah dan Jawa menunjukkan unsur baru diterima tetapi ciri khas budaya Jawa tetap terlihat. 3. Oleh karena itu bangunan tersebut merupakan contoh akulturasi, sedangkan hilangnya bahasa daerah justru menunjukkan asimilasi." },
    { q: "Sekolah yang menjadi ajang mencari jodoh atau memperluas pergaulan menunjukkan fungsi lembaga pendidikan yang bersifat ....", options: ["manifes", "primer", "formal", "laten"], answer: 3, solution: "1. Menurut Robert K. Merton, fungsi manifes adalah fungsi yang nyata dan disadari, sedangkan fungsi laten adalah fungsi yang tersembunyi dan tidak disadari. 2. Fungsi utama sekolah yang disadari adalah mendidik, sedangkan menjadi ajang mencari jodoh bukanlah tujuan resmi yang disadari. 3. Karena fungsi tersebut tersembunyi dan tidak disadari sebagai tujuan utama, maka disebut fungsi laten." },
    { q: "Tujuan utama lembaga pendidikan, yaitu mencerdaskan dan membekali peserta didik dengan ilmu pengetahuan, disebut fungsi ....", options: ["manifes", "laten", "tersembunyi", "disfungsi"], answer: 0, solution: "1. Fungsi manifes menurut Merton adalah fungsi lembaga yang nyata, diharapkan, dan disadari oleh masyarakat. 2. Mencerdaskan peserta didik adalah tujuan resmi dan disadari dari didirikannya lembaga pendidikan. 3. Karena fungsi ini nyata dan sesuai tujuan pendirian lembaga, maka disebut fungsi manifes." },
    { q: "Fungsi lembaga keluarga yang berkaitan dengan pemenuhan kebutuhan kasih sayang antaranggota keluarga disebut fungsi ....", options: ["ekonomi", "afeksi", "reproduksi", "proteksi"], answer: 1, solution: "1. Lembaga keluarga memiliki beberapa fungsi, antara lain fungsi reproduksi, ekonomi, proteksi, sosialisasi, dan afeksi. 2. Fungsi afeksi adalah fungsi pemenuhan kebutuhan kasih sayang dan rasa aman secara emosional antaranggota keluarga. 3. Oleh karena itu pemenuhan kebutuhan kasih sayang termasuk fungsi afeksi." },
    { q: "Lembaga sosial yang berfungsi mengatur hubungan manusia dengan Tuhan Yang Maha Esa adalah lembaga ....", options: ["pendidikan", "ekonomi", "agama", "politik"], answer: 2, solution: "1. Setiap lembaga sosial memiliki fungsi khusus sesuai bidang kehidupannya. 2. Lembaga agama mengatur tata cara hubungan manusia dengan Tuhan, misalnya melalui ibadah dan ajaran keagamaan. 3. Oleh karena itu lembaga yang mengatur hubungan manusia dengan Tuhan Yang Maha Esa adalah lembaga agama." },
    { q: "Kegiatan produksi, distribusi, dan konsumsi barang dan jasa dalam masyarakat diatur oleh lembaga ....", options: ["politik", "keluarga", "pendidikan", "ekonomi"], answer: 3, solution: "1. Lembaga ekonomi adalah lembaga yang mengatur kegiatan pemenuhan kebutuhan hidup manusia. 2. Kegiatan produksi (membuat barang), distribusi (menyalurkan barang), dan konsumsi (memakai barang) adalah ruang lingkup kegiatan ekonomi. 3. Oleh karena itu kegiatan tersebut diatur oleh lembaga ekonomi." },
    { q: "Lembaga yang berfungsi menjaga ketertiban dan mengatur penggunaan kekuasaan dalam masyarakat adalah lembaga ....", options: ["politik", "ekonomi", "agama", "keluarga"], answer: 0, solution: "1. Lembaga politik adalah lembaga yang mengatur kekuasaan dan tata pemerintahan dalam masyarakat. 2. Fungsi utamanya adalah menjaga ketertiban, keamanan, dan mengatur hubungan kekuasaan antarwarga negara. 3. Oleh karena itu lembaga yang menjaga ketertiban dan mengatur kekuasaan adalah lembaga politik." },
    { q: "Langkah pertama yang harus dilakukan dalam penelitian sosial adalah ....", options: ["mengumpulkan data di lapangan", "merumuskan masalah penelitian", "menganalisis data yang terkumpul", "menarik kesimpulan penelitian"], answer: 1, solution: "1. Langkah-langkah penelitian sosial meliputi: merumuskan masalah, menyusun teori dan hipotesis, mengumpulkan data, menganalisis data, dan menarik kesimpulan. 2. Rumusan masalah menjadi arah dan pedoman seluruh kegiatan penelitian berikutnya. 3. Oleh karena itu langkah pertama penelitian sosial adalah merumuskan masalah penelitian." },
    { q: "Penelitian yang datanya berupa angka-angka dan dianalisis menggunakan perhitungan statistik disebut penelitian ....", options: ["kualitatif", "deskriptif", "kuantitatif", "historis"], answer: 2, solution: "1. Metode kuantitatif adalah metode penelitian yang datanya berupa angka dan dianalisis dengan teknik statistik. 2. Penelitian kualitatif sebaliknya datanya berupa kata-kata atau makna dan tidak menggunakan perhitungan statistik. 3. Karena datanya berupa angka dan dianalisis secara statistik, penelitian ini disebut penelitian kuantitatif." },
    { q: "Teknik pengambilan sampel di mana setiap anggota populasi memiliki peluang yang sama untuk dipilih menjadi sampel disebut ....", options: ["purposive sampling", "snowball sampling", "quota sampling", "random sampling"], answer: 3, solution: "1. Teknik sampling dibedakan menjadi probability sampling dan non-probability sampling. 2. Random sampling termasuk probability sampling karena setiap anggota populasi memiliki peluang yang sama untuk terpilih secara acak. 3. Purposive, snowball, dan quota sampling termasuk non-probability sampling karena pemilihannya tidak acak, sehingga jawabannya adalah random sampling." },
    { q: "Data yang diperoleh peneliti secara langsung dari sumber pertama, misalnya dari hasil wawancara, disebut data ....", options: ["primer", "sekunder", "tersier", "kuantitatif"], answer: 0, solution: "1. Data primer adalah data yang diperoleh peneliti secara langsung dari sumber pertama di lapangan. 2. Hasil wawancara yang dilakukan sendiri oleh peneliti termasuk data yang langsung diperoleh dari sumbernya. 3. Data sekunder sebaliknya diperoleh dari sumber yang sudah ada, misalnya dokumen atau laporan orang lain, sehingga jawabannya adalah data primer." },
    { q: "Metode pengumpulan data yang paling sesuai untuk penelitian kualitatif tentang makna ritual adat suatu masyarakat adalah ....", options: ["kuesioner tertutup", "wawancara mendalam", "survei daring", "eksperimen laboratorium"], answer: 1, solution: "1. Penelitian kualitatif bertujuan memahami makna suatu gejala sosial secara mendalam, bukan mengukur dengan angka. 2. Wawancara mendalam memungkinkan peneliti menggali makna ritual adat langsung dari pelaku budaya secara rinci. 3. Kuesioner tertutup dan survei lebih cocok untuk penelitian kuantitatif, sedangkan eksperimen tidak sesuai untuk kajian makna budaya, sehingga jawabannya adalah wawancara mendalam." },
{ q: "Menurut Soerjono Soekanto, interaksi sosial adalah ....", options: ["hubungan timbal balik yang dinamis antara individu dengan individu, individu dengan kelompok, atau kelompok dengan kelompok", "hubungan searah dari individu yang lebih kuat kepada individu yang lebih lemah", "sekumpulan individu yang kebetulan berada di tempat yang sama tanpa saling berhubungan", "proses penyesuaian diri individu terhadap lingkungan alam sekitarnya"], answer: 0, solution: "1. Menurut Soerjono Soekanto, interaksi sosial adalah hubungan-hubungan sosial yang dinamis. 2. Hubungan tersebut menyangkut hubungan antara individu dengan individu, individu dengan kelompok, atau kelompok dengan kelompok. 3. Kata kuncinya adalah timbal balik dan dinamis, bukan hubungan searah atau sekadar kebetulan berada di tempat yang sama. Jadi, jawaban yang tepat adalah hubungan timbal balik yang dinamis tersebut." },
  { q: "Dua orang yang tidak saling kenal mengobrol akrab melalui sambungan telepon. Peristiwa tersebut termasuk interaksi sosial karena memenuhi syarat ....", options: ["adanya kontak sosial saja", "adanya komunikasi saja", "adanya kontak sosial dan komunikasi", "adanya imitasi dan sugesti"], answer: 2, solution: "1. Syarat terjadinya interaksi sosial ada dua, yaitu kontak sosial dan komunikasi. 2. Mengobrol melalui telepon merupakan kontak tidak langsung (sekunder) yang disertai komunikasi verbal. 3. Karena kedua syarat terpenuhi, peristiwa tersebut termasuk interaksi sosial, sedangkan imitasi dan sugesti hanyalah faktor pendorong. Jadi, jawaban yang tepat adalah adanya kontak sosial dan komunikasi." },
  { q: "Seorang guru menjelaskan materi sambil bertatap muka langsung dengan para muridnya. Bentuk kontak sosial tersebut adalah kontak ....", options: ["sekunder", "primer", "negatif", "tidak langsung"], answer: 1, solution: "1. Kontak primer adalah kontak sosial yang terjadi secara langsung tanpa perantara. 2. Guru menjelaskan materi sambil bertatap muka langsung dengan muridnya. 3. Karena tidak ada perantara, kontak tersebut tergolong primer, bukan sekunder. Jadi, jawaban yang tepat adalah kontak primer." },
  { q: "Seorang pelanggan memesan makanan melalui aplikasi pesan-antar daring. Bentuk kontak sosial antara pelanggan dan penjual tersebut adalah kontak ....", options: ["primer", "langsung", "sekunder", "positif"], answer: 2, solution: "1. Kontak sekunder adalah kontak sosial yang terjadi melalui perantara atau media. 2. Pelanggan memesan makanan melalui aplikasi, sehingga ada perantara teknologi. 3. Kontak primer justru terjadi secara langsung tanpa perantara seperti tatap muka. Jadi, jawaban yang tepat adalah kontak sekunder." },
  { q: "Warga bergotong royong memperbaiki jalan desa yang rusak. Kontak sosial tersebut bersifat ....", options: ["negatif karena melelahkan", "netral karena tidak ada komunikasi", "sekunder karena dilakukan berkelompok", "positif karena mengarah pada kerja sama"], answer: 3, solution: "1. Kontak positif adalah kontak sosial yang mengarah pada kerja sama dan keharmonisan. 2. Gotong royong memperbaiki jalan desa adalah kerja sama yang bermanfaat bagi semua warga. 3. Kontak negatif justru mengarah pada pertentangan dan kerugian. Jadi, jawaban yang tepat adalah positif karena mengarah pada kerja sama." },
  { q: "Tawuran antarpelajar yang menimbulkan korban luka merupakan contoh kontak sosial yang bersifat ....", options: ["positif", "primer", "negatif", "asosiatif"], answer: 2, solution: "1. Kontak negatif adalah kontak sosial yang mengarah pada pertentangan dan merugikan pihak lain. 2. Tawuran antarpelajar menimbulkan korban luka dan kerugian. 3. Karena bersifat merusak, tawuran tergolong kontak negatif, bukan positif atau asosiatif. Jadi, jawaban yang tepat adalah negatif." },
  { q: "Berikut ini yang termasuk contoh komunikasi verbal adalah ....", options: ["melambaikan tangan kepada teman", "berpidato di depan kelas", "menganggukkan kepala tanda setuju", "tersenyum kepada orang yang disapa"], answer: 1, solution: "1. Komunikasi verbal adalah komunikasi yang menggunakan kata-kata, baik lisan maupun tulisan. 2. Berpidato menyampaikan pesan melalui kata-kata yang diucapkan. 3. Melambaikan tangan, mengangguk, dan tersenyum tidak menggunakan kata-kata sehingga termasuk nonverbal. Jadi, jawaban yang tepat adalah berpidato di depan kelas." },
  { q: "Seorang wasit meniup peluit panjang sambil mengacungkan kartu merah kepada pemain. Bentuk komunikasi yang digunakan wasit tersebut adalah komunikasi ....", options: ["verbal", "langsung", "sekunder", "nonverbal"], answer: 3, solution: "1. Komunikasi nonverbal menyampaikan pesan tanpa kata-kata, misalnya melalui isyarat atau bunyi. 2. Tiupan peluit dan acungan kartu merah adalah isyarat yang maknanya dipahami tanpa diucapkan. 3. Karena tidak ada kata-kata lisan atau tulisan, komunikasi tersebut tergolong nonverbal. Jadi, jawaban yang tepat adalah nonverbal." },
  { q: "Ketika ditanya guru, seorang siswa menganggukkan kepalanya. Isyarat nonverbal tersebut bermakna ....", options: ["menolak pertanyaan guru", "bingung dan tidak paham", "setuju atau mengiyakan", "meminta izin keluar kelas"], answer: 2, solution: "1. Bahasa tubuh termasuk komunikasi nonverbal yang maknanya disepakati secara sosial. 2. Menganggukkan kepala secara umum dimaknai sebagai tanda setuju atau mengiyakan. 3. Sedangkan menggelengkan kepala berarti menolak. Jadi, jawaban yang tepat adalah setuju atau mengiyakan." },
  { q: "Sinta meniru kebiasaan kakaknya yang rajin membaca buku setiap malam. Tindakan Sinta termasuk imitasi yang bersifat ....", options: ["positif", "negatif", "netral", "pasif"], answer: 0, solution: "1. Imitasi adalah tindakan meniru sikap atau perilaku orang lain. 2. Imitasi positif adalah meniru hal-hal yang baik dan bermanfaat. 3. Rajin membaca buku adalah kebiasaan baik, sehingga tiruan Sinta bersifat positif. Jadi, jawaban yang tepat adalah positif." },
  { q: "Sekelompok remaja meniru aksi geng motor yang sering membuat onar di jalan. Imitasi tersebut bersifat ....", options: ["positif karena kompak", "negatif karena merugikan", "netral karena sekadar meniru", "asosiatif karena berkelompok"], answer: 1, solution: "1. Imitasi negatif adalah meniru perilaku yang buruk dan merugikan. 2. Aksi geng motor membuat onar dan membahayakan orang lain. 3. Kekompakan tidak mengubah perilaku merusak menjadi positif. Jadi, jawaban yang tepat adalah negatif karena merugikan." },
  { q: "Seorang anak bercita-cita menjadi dokter seperti ayahnya dan meniru seluruh kebiasaan serta gaya hidup ayahnya. Proses tersebut disebut ....", options: ["imitasi", "sugesti", "identifikasi", "simpati"], answer: 2, solution: "1. Identifikasi adalah kecenderungan seseorang untuk menjadi sama dengan pihak lain yang dikaguminya. 2. Anak tersebut tidak sekadar meniru, tetapi ingin menjadi sama persis seperti ayahnya. 3. Imitasi hanya meniru perilaku yang tampak, sedangkan simpati berkaitan dengan perasaan. Jadi, jawaban yang tepat adalah identifikasi." },
  { q: "Rudi merasa tertarik dan ikut sedih mendengar cerita temannya yang kehilangan dompet. Sikap Rudi tersebut disebut ....", options: ["simpati", "empati", "identifikasi", "motivasi"], answer: 0, solution: "1. Simpati adalah proses kejiwaan ketika seseorang merasa tertarik pada pihak lain dan ikut merasakan perasaannya. 2. Rudi ikut sedih mendengar cerita temannya, yang menunjukkan ketertarikan perasaan. 3. Empati lebih dalam, yaitu seolah-olah mengalami sendiri perasaan itu. Jadi, jawaban yang tepat adalah simpati." },
  { q: "Seorang relawan banjir mampu memahami penderitaan korban seolah-olah dirinya sendiri yang mengalaminya, sehingga ia tergerak membantu dengan sungguh-sungguh. Kemampuan tersebut disebut ....", options: ["simpati", "empati", "sugesti", "imitasi"], answer: 1, solution: "1. Empati adalah kemampuan ikut merasakan keadaan orang lain seolah-olah mengalami sendiri. 2. Relawan tersebut mendalami penderitaan korban hingga seperti mengalaminya sendiri. 3. Simpati hanya sebatas ikut merasakan, tidak sedalam empati. Jadi, jawaban yang tepat adalah empati." },
  { q: "Perbedaan utama antara simpati dan empati adalah ....", options: ["simpati lebih dalam daripada empati", "empati hanya berupa ketertarikan sesaat, sedangkan simpati berlangsung lama", "simpati adalah ikut merasakan perasaan orang lain, sedangkan empati merasakan seolah-olah mengalami sendiri", "keduanya tidak memiliki perbedaan yang berarti"], answer: 2, solution: "1. Simpati adalah ketertarikan dan ikut merasakan perasaan orang lain. 2. Empati lebih mendalam, yaitu memahami dan merasakan seolah-olah diri sendiri yang mengalami. 3. Jadi empati berada satu tingkat lebih dalam daripada simpati. Jadi, jawaban yang tepat adalah simpati ikut merasakan, sedangkan empati seolah mengalami sendiri." },
  { q: "Setelah melihat iklan di televisi, seseorang langsung membeli produk tersebut tanpa mempertimbangkan baik-buruknya. Pengaruh iklan tersebut merupakan contoh ....", options: ["imitasi", "sugesti", "identifikasi", "motivasi"], answer: 1, solution: "1. Sugesti adalah pengaruh yang diterima seseorang tanpa berpikir kritis atau mempertimbangkan baik-buruknya. 2. Pembeli terpengaruh iklan dan langsung membeli tanpa pertimbangan. 3. Imitasi adalah meniru perilaku yang tampak, bukan terpengaruh pendapat. Jadi, jawaban yang tepat adalah sugesti." },
  { q: "Perbedaan imitasi dan sugesti terletak pada ....", options: ["imitasi meniru perilaku yang tampak, sedangkan sugesti menerima pengaruh tanpa pertimbangan kritis", "imitasi bersifat negatif, sedangkan sugesti selalu positif", "imitasi hanya terjadi pada anak-anak, sedangkan sugesti pada orang dewasa", "keduanya adalah proses yang sama dengan nama berbeda"], answer: 0, solution: "1. Imitasi adalah meniru tindakan atau perilaku orang lain yang dapat diamati. 2. Sugesti adalah menerima pandangan atau pengaruh orang lain tanpa daya kritis. 3. Keduanya sama-sama faktor pendorong interaksi, tetapi mekanismenya berbeda. Jadi, jawaban yang tepat adalah imitasi meniru perilaku yang tampak, sedangkan sugesti menerima pengaruh tanpa pertimbangan kritis." },
  { q: "Seorang siswa giat berlatih basket setiap sore karena bercita-cita masuk tim basket provinsi. Dorongan dalam diri siswa tersebut disebut ....", options: ["sugesti", "imitasi", "simpati", "motivasi"], answer: 3, solution: "1. Motivasi adalah dorongan dari dalam diri untuk mencapai tujuan tertentu. 2. Siswa tersebut berlatih giat karena memiliki cita-cita yang ingin dicapai. 3. Sugesti datang dari pengaruh luar, sedangkan motivasi lahir dari dalam diri. Jadi, jawaban yang tepat adalah motivasi." },
  { q: "Warga desa membangun jembatan secara bersama-sama tanpa mengharap upah. Bentuk kerja sama tersebut disebut ....", options: ["bargaining", "koalisi", "gotong royong", "joint venture"], answer: 2, solution: "1. Gotong royong adalah kerja sama spontan untuk kepentingan bersama tanpa mengharap imbalan. 2. Warga membangun jembatan bersama tanpa upah demi kepentingan desa. 3. Bargaining adalah tawar-menawar, sedangkan joint venture adalah patungan modal usaha. Jadi, jawaban yang tepat adalah gotong royong." },
  { q: "Penjual dan pembeli di pasar saling tawar-menawar harga hingga mencapai kesepakatan. Bentuk kerja sama tersebut disebut ....", options: ["kooptasi", "bargaining", "koalisi", "koersi"], answer: 1, solution: "1. Bargaining adalah bentuk kerja sama berupa tawar-menawar atau negosiasi untuk mencapai kesepakatan. 2. Penjual dan pembeli bernegosiasi soal harga sampai sepakat. 3. Kooptasi adalah penerimaan unsur baru dalam kepemimpinan, bukan tawar-menawar. Jadi, jawaban yang tepat adalah bargaining." },
  { q: "Untuk meredam penentangan, sebuah organisasi menerima tokoh dari kelompok lawan menjadi salah satu pengurusnya. Strategi tersebut disebut ....", options: ["kooptasi", "koalisi", "kompromi", "konsiliasi"], answer: 0, solution: "1. Kooptasi adalah cara menerima unsur-unsur baru dalam kepemimpinan suatu organisasi untuk menghindari kegoncangan. 2. Tokoh lawan dijadikan pengurus agar tidak menentang dari luar. 3. Koalisi adalah gabungan organisasi, sedangkan kompromi adalah saling mengurangi tuntutan. Jadi, jawaban yang tepat adalah kooptasi." },
  { q: "Beberapa partai politik bergabung untuk mengusung calon yang sama dalam pemilihan kepala daerah. Gabungan partai-partai tersebut disebut ....", options: ["joint venture", "koalisi", "kooptasi", "akomodasi"], answer: 1, solution: "1. Koalisi adalah gabungan dua organisasi atau lebih yang memiliki tujuan yang sama. 2. Partai-partai bergabung dengan tujuan bersama memenangkan pilkada. 3. Joint venture adalah kerja sama patungan modal usaha. Jadi, jawaban yang tepat adalah koalisi." },
  { q: "Dua perusahaan sepakat patungan modal untuk mendirikan pabrik baru dan berbagi keuntungan. Bentuk kerja sama tersebut disebut ....", options: ["koalisi", "bargaining", "toleransi", "joint venture"], answer: 3, solution: "1. Joint venture adalah kerja sama dalam bentuk usaha patungan dengan modal dan keuntungan bersama. 2. Dua perusahaan menanam modal bersama untuk pabrik baru. 3. Koalisi adalah gabungan organisasi politik, bukan patungan usaha. Jadi, jawaban yang tepat adalah joint venture." },
  { q: "Pemerintah mengenakan denda kepada warga yang membuang sampah sembarangan agar tertib. Penyelesaian masalah dengan ancaman atau paksaan tersebut disebut ....", options: ["kompromi", "koersi", "toleransi", "mediasi"], answer: 1, solution: "1. Koersi adalah bentuk akomodasi yang dilaksanakan dengan paksaan atau ancaman. 2. Denda adalah ancaman agar warga mematuhi aturan. 3. Kompromi adalah saling mengurangi tuntutan secara sukarela, bukan paksaan. Jadi, jawaban yang tepat adalah koersi." },
  { q: "Dua pihak yang bertikai masing-masing bersedia mengurangi tuntutannya hingga tercapai kesepakatan. Cara penyelesaian tersebut disebut ....", options: ["kompromi", "koersi", "stalemate", "adjudikasi"], answer: 0, solution: "1. Kompromi adalah bentuk akomodasi di mana pihak-pihak yang berselisih saling mengurangi tuntutannya. 2. Kedua pihak sama-sama mengalah sebagian demi kesepakatan. 3. Koersi menggunakan paksaan, sedangkan stalemate adalah kebuntuan karena kekuatan seimbang. Jadi, jawaban yang tepat adalah kompromi." },
  { q: "Umat beragama yang berbeda saling menghormati perayaan hari besar masing-masing tanpa saling mencampuri. Sikap tersebut merupakan bentuk akomodasi berupa ....", options: ["toleransi", "koersi", "kompromi", "kontravensi"], answer: 0, solution: "1. Toleransi adalah bentuk akomodasi berupa sikap menghormati dan membiarkan pihak lain tanpa persetujuan formal. 2. Umat beragama saling menghormati tanpa mencampuri urusan masing-masing. 3. Kontravensi justru mengarah pada pertentangan terselubung. Jadi, jawaban yang tepat adalah toleransi." },
  { q: "Dua kubu yang berseteru memiliki kekuatan seimbang sehingga pertikaian berhenti dengan sendirinya tanpa ada pemenang. Keadaan tersebut disebut ....", options: ["kompromi", "stalemate", "toleransi", "asimilasi"], answer: 1, solution: "1. Stalemate adalah keadaan ketika pihak-pihak yang bertentangan memiliki kekuatan seimbang sehingga pertentangan terhenti. 2. Kedua kubu sama kuat sehingga tidak ada yang menang dan pertikaian berhenti. 3. Kompromi membutuhkan kesepakatan aktif, sedangkan stalemate berhenti karena kebuntuan. Jadi, jawaban yang tepat adalah stalemate." },
  { q: "Perbedaan mediasi dan konsiliasi dalam penyelesaian sengketa adalah ....", options: ["mediasi mempertemukan pihak bersengketa, sedangkan konsiliasi memutuskan perkara", "keduanya sama-sama memutuskan perkara secara mengikat", "mediasi menghadirkan pihak ketiga sebagai penasihat, sedangkan konsiliasi mempertemukan pihak bersengketa agar berunding mencapai persetujuan", "mediasi dilakukan di pengadilan, sedangkan konsiliasi di luar pengadilan"], answer: 2, solution: "1. Mediasi adalah penyelesaian sengketa dengan bantuan pihak ketiga sebagai penasihat, tetapi keputusan tetap di tangan pihak yang bersengketa. 2. Konsiliasi adalah usaha mempertemukan pihak-pihak yang berselisih agar mereka berunding dan mencapai persetujuan sendiri. 3. Keduanya tidak memutuskan perkara secara mengikat seperti arbitrasi atau ajudikasi. Jadi, jawaban yang tepat adalah mediasi menghadirkan penasihat, sedangkan konsiliasi mempertemukan pihak bersengketa." },
  { q: "Perbedaan asimilasi dan akulturasi terletak pada ....", options: ["asimilasi mempertahankan ciri khas budaya, sedangkan akulturasi menghilangkannya", "asimilasi meleburkan kebudayaan asli hingga hilang, sedangkan akulturasi menerima unsur asing tanpa menghilangkan ciri khas budaya sendiri", "asimilasi hanya terjadi pada bahasa, sedangkan akulturasi pada kesenian", "keduanya memiliki pengertian yang sama"], answer: 1, solution: "1. Asimilasi adalah peleburan dua kebudayaan atau lebih sehingga kebudayaan asli melebur dan menghasilkan kebudayaan baru. 2. Akulturasi adalah masuknya unsur kebudayaan asing tanpa menghilangkan ciri khas kebudayaan sendiri. 3. Jadi asimilasi menghilangkan, sedangkan akulturasi memadukan. Jadi, jawaban yang tepat adalah asimilasi meleburkan hingga hilang, sedangkan akulturasi tanpa menghilangkan ciri khas." },
  { q: "Musik keroncong yang memadukan unsur musik Portugis dengan musik tradisional tanpa menghilangkan ciri keduanya merupakan contoh ....", options: ["asimilasi", "kontravensi", "difusi", "akulturasi"], answer: 3, solution: "1. Akulturasi adalah perpaduan unsur kebudayaan asing dengan kebudayaan sendiri tanpa menghilangkan ciri khas masing-masing. 2. Keroncong memadukan unsur Portugis dan tradisi lokal dan keduanya tetap dikenali. 3. Asimilasi akan menghilangkan salah satu kebudayaan hingga melebur. Jadi, jawaban yang tepat adalah akulturasi." },
  { q: "Akibat perkawinan campuran, anak-anak dari pasangan tersebut hanya mengenal kebudayaan salah satu pihak karena kebudayaan pihak lain telah melebur dan hilang. Peristiwa tersebut disebut ....", options: ["akulturasi", "asimilasi", "toleransi", "integrasi"], answer: 1, solution: "1. Asimilasi adalah proses peleburan kebudayaan sehingga kebudayaan asli hilang dan melebur ke kebudayaan lain. 2. Kebudayaan salah satu pihak hilang sepenuhnya dan anak-anak hanya mengenal satu kebudayaan. 3. Akulturasi justru mempertahankan ciri khas budaya asal. Jadi, jawaban yang tepat adalah asimilasi." },
  { q: "Dua toko kelontong bersaing memberikan pelayanan terbaik agar pelanggan memilih tokonya. Bentuk interaksi tersebut adalah ....", options: ["konflik", "kontravensi", "persaingan", "koersi"], answer: 2, solution: "1. Persaingan atau kompetisi adalah usaha mencapai tujuan dengan cara damai tanpa kekerasan. 2. Kedua toko bersaing secara sehat melalui pelayanan terbaik. 3. Konflik disertai ancaman atau kekerasan, sedangkan kontravensi bersifat terselubung. Jadi, jawaban yang tepat adalah persaingan." },
  { q: "Perbedaan persaingan (kompetisi) dan konflik adalah ....", options: ["persaingan dilakukan dengan cara damai tanpa kekerasan, sedangkan konflik disertai ancaman atau kekerasan", "persaingan disertai kekerasan, sedangkan konflik dilakukan damai", "keduanya sama-sama menggunakan kekerasan", "persaingan selalu merugikan, sedangkan konflik menguntungkan"], answer: 0, solution: "1. Persaingan adalah bentuk interaksi disosiatif yang dilakukan secara sehat tanpa kekerasan untuk mencapai tujuan. 2. Konflik adalah pertentangan yang disertai ancaman atau kekerasan. 3. Jadi pembedanya adalah ada tidaknya kekerasan. Jadi, jawaban yang tepat adalah persaingan damai tanpa kekerasan, sedangkan konflik disertai ancaman atau kekerasan." },
  { q: "Sebuah kelompok menyebarkan fitnah untuk menjatuhkan kelompok lain tanpa melakukan konfrontasi terbuka. Tindakan tersebut termasuk ....", options: ["persaingan sehat", "kontravensi", "kompromi", "koalisi"], answer: 1, solution: "1. Kontravensi adalah bentuk persaingan terselubung seperti provokasi, fitnah, intimidasi, dan penghasutan. 2. Penyebaran fitnah dilakukan diam-diam tanpa konfrontasi terbuka. 3. Persaingan sehat dilakukan terbuka tanpa cara curang. Jadi, jawaban yang tepat adalah kontravensi." },
  { q: "Perbedaan kontravensi dan persaingan terletak pada ....", options: ["kontravensi selalu disertai kekerasan fisik", "persaingan bersifat terselubung, sedangkan kontravensi terbuka", "keduanya tidak memiliki perbedaan", "kontravensi dilakukan secara terselubung, sedangkan persaingan dilakukan secara terbuka"], answer: 3, solution: "1. Kontravensi adalah bentuk interaksi disosiatif yang bersifat tersembunyi, misalnya fitnah dan provokasi. 2. Persaingan dilakukan secara terbuka dan sehat untuk mencapai tujuan. 3. Keduanya tidak menggunakan kekerasan terbuka seperti konflik. Jadi, jawaban yang tepat adalah kontravensi terselubung, sedangkan persaingan terbuka." },
  { q: "Seorang siswa memilih jurusan IPA karena ingin menjadi dokter dan telah memperhitungkan peluangnya dengan matang. Menurut Max Weber, tindakan tersebut termasuk tindakan ....", options: ["rasional berorientasi nilai", "afektif", "tradisional", "rasional instrumental"], answer: 3, solution: "1. Tindakan rasional instrumental adalah tindakan yang dilakukan dengan mempertimbangkan tujuan dan cara yang paling efisien. 2. Siswa tersebut memilih jurusan dengan perhitungan matang demi tujuannya menjadi dokter. 3. Tindakan berorientasi nilai didorong keyakinan, bukan perhitungan untung rugi. Jadi, jawaban yang tepat adalah rasional instrumental." },
  { q: "Seseorang menjalankan puasa sunah karena keyakinan agamanya, bukan karena ingin dipuji orang lain. Menurut Max Weber, tindakan tersebut termasuk tindakan ....", options: ["rasional instrumental", "rasional berorientasi nilai", "afektif", "tradisional"], answer: 1, solution: "1. Tindakan rasional berorientasi nilai didorong oleh keyakinan pada nilai-nilai yang dianut, tanpa memperhitungkan untung rugi. 2. Puasa tersebut dilakukan karena keyakinan agama, bukan perhitungan manfaat. 3. Tindakan instrumental justru penuh perhitungan tujuan. Jadi, jawaban yang tepat adalah rasional berorientasi nilai." },
  { q: "Seorang suporter melempar botol ke lapangan karena kecewa tim kesayangannya kalah. Tindakan yang didorong luapan emosi tersebut menurut Max Weber disebut tindakan ....", options: ["afektif", "tradisional", "rasional instrumental", "rasional berorientasi nilai"], answer: 0, solution: "1. Tindakan afektif adalah tindakan yang didorong oleh perasaan atau emosi sesaat. 2. Suporter tersebut bertindak karena kecewa, bukan karena pertimbangan rasional. 3. Tindakan tradisional didorong kebiasaan turun-temurun. Jadi, jawaban yang tepat adalah afektif." },
  { q: "Masyarakat desa mengadakan sedekah bumi setiap tahun karena sudah menjadi kebiasaan turun-temurun. Menurut Max Weber, tindakan tersebut termasuk tindakan ....", options: ["afektif", "rasional instrumental", "tradisional", "rasional berorientasi nilai"], answer: 2, solution: "1. Tindakan tradisional adalah tindakan yang dilakukan karena kebiasaan atau adat yang diwariskan turun-temurun. 2. Sedekah bumi dilakukan karena sudah menjadi tradisi desa. 3. Tindakan afektif didorong emosi sesaat, bukan kebiasaan. Jadi, jawaban yang tepat adalah tradisional." },
  { q: "Perbedaan tindakan rasional instrumental dan rasional berorientasi nilai menurut Max Weber adalah ....", options: ["rasional instrumental mempertimbangkan tujuan dan cara paling efisien, sedangkan rasional berorientasi nilai didorong keyakinan tanpa memperhitungkan untung rugi", "rasional instrumental didorong emosi, sedangkan rasional berorientasi nilai didorong kebiasaan", "keduanya sama-sama didorong oleh emosi sesaat", "rasional instrumental tidak mempertimbangkan tujuan sama sekali"], answer: 0, solution: "1. Tindakan rasional instrumental berorientasi pada tujuan dengan perhitungan cara yang paling tepat dan efisien. 2. Tindakan rasional berorientasi nilai didorong oleh keyakinan terhadap nilai yang dianut, tanpa perhitungan untung rugi. 3. Tindakan afektif yang didorong emosi dan tradisional yang didorong kebiasaan adalah jenis yang berbeda. Jadi, jawaban yang tepat adalah pernyataan pertama." },
  { q: "Proses sosialisasi yang pertama kali dialami anak dan berlangsung dalam lingkungan keluarga disebut sosialisasi ....", options: ["sekunder", "primer", "formal", "tersier"], answer: 1, solution: "1. Sosialisasi primer adalah sosialisasi pertama yang dialami individu pada masa kanak-kanak. 2. Sosialisasi ini berlangsung dalam keluarga sebagai lingkungan terdekat. 3. Sosialisasi sekunder terjadi kemudian melalui sekolah, teman sebaya, dan media massa. Jadi, jawaban yang tepat adalah primer." },
  { q: "Melalui sekolah, seorang anak belajar disiplin, tata tertib, dan bekerja sama dengan teman-temannya. Proses tersebut merupakan sosialisasi ....", options: ["primer", "informal", "primer dan sekunder", "sekunder"], answer: 3, solution: "1. Sosialisasi sekunder adalah sosialisasi lanjutan yang terjadi di luar keluarga. 2. Sekolah menanamkan disiplin dan kerja sama sebagai bekal hidup bermasyarakat. 3. Sosialisasi primer hanya berlangsung dalam keluarga pada masa kanak-kanak. Jadi, jawaban yang tepat adalah sekunder." },
  { q: "Nilai kejujuran dan sopan santun pertama kali ditanamkan kepada anak melalui ....", options: ["sekolah", "teman sebaya", "keluarga", "media massa"], answer: 2, solution: "1. Keluarga adalah agen sosialisasi pertama dan utama bagi anak. 2. Nilai-nilai dasar seperti kejujuran dan sopan santun ditanamkan orang tua sejak dini. 3. Sekolah dan media massa berperan pada tahap sosialisasi berikutnya. Jadi, jawaban yang tepat adalah keluarga." },
  { q: "Seorang remaja belajar gaya berpakaian dan bahasa pergaulan dari teman-teman sebayanya. Agen sosialisasi yang berperan dalam hal tersebut adalah ....", options: ["teman sebaya", "keluarga", "sekolah", "lingkungan kerja"], answer: 0, solution: "1. Teman sebaya adalah agen sosialisasi yang berpengaruh besar pada masa remaja. 2. Gaya berpakaian dan bahasa gaul dipelajari dari pergaulan dengan teman sebaya. 3. Keluarga berperan pada nilai dasar, bukan tren pergaulan remaja. Jadi, jawaban yang tepat adalah teman sebaya." },
  { q: "Sikap dan gaya hidup remaja yang banyak dipengaruhi tayangan televisi dan media sosial menunjukkan peran agen sosialisasi ....", options: ["keluarga", "media massa", "sekolah", "teman sebaya"], answer: 1, solution: "1. Media massa adalah agen sosialisasi yang menyampaikan nilai, sikap, dan gaya hidup melalui tayangan dan konten. 2. Televisi dan media sosial membentuk selera dan gaya hidup remaja. 3. Pengaruh ini datang dari media, bukan dari interaksi langsung. Jadi, jawaban yang tepat adalah media massa." },
  { q: "Seorang guru berstatus sebagai pendidik. Kewajibannya mengajar dan mendidik para siswa merupakan ....", options: ["status sosialnya", "kepribadiannya", "kedudukannya", "peran sosialnya"], answer: 3, solution: "1. Status adalah kedudukan seseorang dalam masyarakat, sedangkan peran adalah pelaksanaan hak dan kewajiban sesuai status tersebut. 2. Guru berstatus pendidik, dan mengajar adalah kewajiban yang dijalankannya. 3. Menjalankan kewajiban sesuai status itulah yang disebut peran. Jadi, jawaban yang tepat adalah peran sosialnya." },
  { q: "Kepribadian seseorang pada dasarnya terbentuk melalui ....", options: ["faktor keturunan semata", "lingkungan alam tempat tinggal", "proses interaksi sosial dan sosialisasi", "bakat yang dibawa sejak lahir"], answer: 2, solution: "1. Kepribadian adalah keseluruhan perilaku dan pola pikir yang terbentuk dari pengalaman sosial. 2. Melalui interaksi sosial dan sosialisasi, individu menyerap nilai dan norma masyarakat. 3. Keturunan dan bakat hanya menjadi dasar, bukan penentu utama. Jadi, jawaban yang tepat adalah proses interaksi sosial dan sosialisasi." },
  { q: "Komentar warganet pada sebuah unggahan media sosial memicu diskusi panjang antarorang yang tidak saling kenal. Fenomena tersebut menunjukkan bahwa interaksi sosial di era digital ....", options: ["tetap membutuhkan tatap muka langsung", "dapat terjadi tanpa terbatas ruang dan waktu melalui media", "tidak lagi membutuhkan komunikasi", "hanya terjadi dalam kelompok kecil"], answer: 1, solution: "1. Media digital memungkinkan kontak sekunder, yaitu kontak melalui perantara teknologi. 2. Warganet yang tidak saling kenal dapat berinteraksi kapan saja dan dari mana saja. 3. Komunikasi tetap ada, hanya medianya yang berubah. Jadi, jawaban yang tepat adalah dapat terjadi tanpa terbatas ruang dan waktu melalui media." },
  { q: "Menurut Soerjono Soekanto, syarat terbentuknya kelompok sosial adalah ....", options: ["setiap anggota sadar sebagai bagian kelompok, ada hubungan timbal balik, dan ada faktor pengikat", "adanya pemimpin yang berkuasa penuh atas anggota", "jumlah anggota yang sangat banyak dan tidak saling kenal", "adanya gedung pertemuan yang permanen"], answer: 0, solution: "1. Menurut Soekanto, kelompok sosial terbentuk bila setiap anggota menyadari dirinya sebagai bagian dari kelompok. 2. Selain itu harus ada hubungan timbal balik antaranggota. 3. Serta ada faktor pengikat seperti kepentingan, tujuan, atau nasib yang sama. Jadi, jawaban yang tepat adalah pernyataan pertama." },
  { q: "Sekumpulan orang berkerumun melihat kecelakaan di jalan belum dapat disebut kelompok sosial karena ....", options: ["jumlahnya terlalu sedikit", "tidak memiliki pemimpin", "berkumpul di tempat umum", "tidak ada kesadaran bersama dan hubungan yang terorganisasi"], answer: 3, solution: "1. Kelompok sosial mensyaratkan kesadaran anggota sebagai bagian kelompok dan hubungan timbal balik yang terorganisasi. 2. Orang yang berkerumun melihat kecelakaan hanya kebetulan berkumpul tanpa kesadaran bersama. 3. Karena syarat kelompok tidak terpenuhi, kerumunan tersebut belum dapat disebut kelompok sosial. Jadi, jawaban yang tepat adalah tidak ada kesadaran bersama dan hubungan yang terorganisasi." },
  { q: "Menurut Charles Horton Cooley, partai politik dan serikat pekerja termasuk kelompok ....", options: ["primer", "paguyuban", "sekunder", "patembayan"], answer: 2, solution: "1. Menurut Cooley, kelompok sekunder adalah kelompok yang hubungan antaranggota bersifat formal dan berorientasi pada tujuan tertentu. 2. Partai politik dan serikat pekerja memiliki struktur formal dan tujuan yang jelas. 3. Kelompok primer justru bersifat pribadi dan akrab seperti keluarga. Jadi, jawaban yang tepat adalah sekunder." },
  { q: "Keluarga besar yang anggotanya terikat hubungan darah dan kasih sayang menurut Ferdinand Tonnies termasuk gemeinschaft ....", options: ["by place", "by blood", "of mind", "by contract"], answer: 1, solution: "1. Menurut Tonnies, gemeinschaft by blood didasarkan pada ikatan keturunan atau darah. 2. Keluarga besar disatukan oleh hubungan darah dan kasih sayang. 3. By place didasarkan pada tempat tinggal, sedangkan of mind pada kesamaan jiwa. Jadi, jawaban yang tepat adalah by blood." },
  { q: "Warga satu RT yang saling mengenal dan tolong-menolong karena tinggal berdekatan termasuk gemeinschaft ....", options: ["by place", "by blood", "of mind", "by interest"], answer: 0, solution: "1. Menurut Tonnies, gemeinschaft by place didasarkan pada kesamaan tempat tinggal. 2. Warga satu RT disatukan karena tinggal berdekatan di wilayah yang sama. 3. By blood didasarkan pada keturunan, bukan tempat tinggal. Jadi, jawaban yang tepat adalah by place." },
  { q: "Komunitas pecinta alam yang anggotanya disatukan oleh kesamaan ide dan cita-cita termasuk gemeinschaft ....", options: ["by blood", "by place", "by contract", "of mind"], answer: 3, solution: "1. Menurut Tonnies, gemeinschaft of mind didasarkan pada kesamaan jiwa, ide, dan cita-cita. 2. Komunitas pecinta alam disatukan oleh kesamaan pandangan dan tujuan. 3. By blood dan by place didasarkan pada keturunan dan tempat tinggal. Jadi, jawaban yang tepat adalah of mind." },
  { q: "Hubungan antara nasabah dan bank yang didasarkan pada perjanjian kredit untuk mencapai tujuan masing-masing termasuk ....", options: ["paguyuban", "gemeinschaft", "gesellschaft", "kelompok primer"], answer: 2, solution: "1. Gesellschaft adalah ikatan sosial yang bersifat formal, kontraktual, dan berorientasi pada tujuan. 2. Hubungan nasabah dan bank didasarkan pada perjanjian untuk mencapai kepentingan masing-masing. 3. Paguyuban dan kelompok primer justru berlandaskan keakraban dan kekeluargaan. Jadi, jawaban yang tepat adalah gesellschaft." },
  { q: "Perbedaan paguyuban dan patembayan adalah ....", options: ["paguyuban berlandaskan hubungan akrab dan kekeluargaan, sedangkan patembayan berlandaskan hubungan formal dan kontraktual", "paguyuban bersifat sementara, sedangkan patembayan bersifat langgeng", "paguyuban berorientasi keuntungan, sedangkan patembayan berorientasi kekeluargaan", "keduanya tidak memiliki perbedaan"], answer: 0, solution: "1. Paguyuban (gemeinschaft) adalah ikatan yang lahir dari keakraban, kekeluargaan, dan berlangsung langgeng. 2. Patembayan (gesellschaft) adalah ikatan yang bersifat formal, kontraktual, dan berorientasi pada tujuan tertentu. 3. Jadi pembedanya adalah dasar hubungan: kekeluargaan versus kontrak. Jadi, jawaban yang tepat adalah pernyataan pertama." },
  { q: "Masyarakat desa yang homogen dengan pembagian kerja sederhana dan kesadaran kolektif yang kuat menurut Emile Durkheim memiliki solidaritas ....", options: ["organik", "individual", "kontraktual", "mekanik"], answer: 3, solution: "1. Menurut Durkheim, solidaritas mekanik terdapat pada masyarakat sederhana yang homogen. 2. Ciri-cirinya adalah pembagian kerja yang sederhana dan kesadaran kolektif yang kuat. 3. Solidaritas organik justru terdapat pada masyarakat modern dengan pembagian kerja kompleks. Jadi, jawaban yang tepat adalah mekanik." },
  { q: "Masyarakat kota modern dengan pembagian kerja yang kompleks dan saling ketergantungan antarprofesi memiliki solidaritas ....", options: ["mekanik", "organik", "tradisional", "primer"], answer: 1, solution: "1. Menurut Durkheim, solidaritas organik terdapat pada masyarakat modern yang heterogen. 2. Ciri-cirinya adalah pembagian kerja yang kompleks dan saling ketergantungan antaranggota. 3. Solidaritas mekanik justru terdapat pada masyarakat tradisional yang homogen. Jadi, jawaban yang tepat adalah organik." },
  { q: "Kelompok tempat seseorang secara resmi terdaftar menjadi anggotanya disebut ....", options: ["reference group", "out-group", "membership group", "kelompok acuan"], answer: 2, solution: "1. Membership group adalah kelompok di mana seseorang secara resmi menjadi anggota. 2. Misalnya seorang siswa adalah anggota resmi kelasnya. 3. Reference group justru adalah kelompok acuan yang belum tentu dianggotai. Jadi, jawaban yang tepat adalah membership group." },
  { q: "Perbedaan membership group dan reference group adalah ....", options: ["membership group adalah kelompok tempat seseorang menjadi anggota, sedangkan reference group adalah kelompok yang dijadikan acuan tanpa harus menjadi anggota", "membership group bersifat acuan, sedangkan reference group bersifat keanggotaan", "keduanya sama-sama menuntut keanggotaan resmi", "reference group selalu lebih kecil daripada membership group"], answer: 0, solution: "1. Membership group adalah kelompok keanggotaan, yaitu kelompok tempat seseorang resmi menjadi anggota. 2. Reference group adalah kelompok acuan, yaitu kelompok yang dijadikan panutan tanpa harus menjadi anggotanya. 3. Jadi pembedanya adalah keanggotaan resmi versus sekadar acuan. Jadi, jawaban yang tepat adalah pernyataan pertama." },
  { q: "Kelompok yang menjadi tempat seseorang menggolongkan dan mengidentifikasi dirinya disebut ....", options: ["out-group", "reference group", "kelompok sekunder", "in-group"], answer: 3, solution: "1. In-group adalah kelompok tempat seseorang merasa menjadi bagian dan menggolongkan dirinya. 2. Misalnya seorang siswa merasa bangga sebagai bagian dari kelasnya. 3. Out-group justru adalah kelompok luar tempat ia tidak menggolongkan diri. Jadi, jawaban yang tepat adalah in-group." },
  { q: "OSIS di sekolah termasuk kelompok formal karena ....", options: ["anggotanya sangat banyak", "memiliki aturan tertulis, struktur pengurus, dan tujuan yang jelas", "berdiri atas dasar keakraban semata", "tidak memiliki anggaran dasar"], answer: 1, solution: "1. Kelompok formal adalah kelompok yang memiliki aturan tertulis, struktur organisasi, dan tujuan yang jelas. 2. OSIS memiliki anggaran dasar, susunan pengurus, dan program kerja resmi. 3. Kelompok yang hanya berdasar keakraban termasuk kelompok informal. Jadi, jawaban yang tepat adalah memiliki aturan tertulis, struktur pengurus, dan tujuan yang jelas." },
  { q: "Arisan ibu-ibu RT yang terbentuk secara spontan atas dasar keakraban termasuk kelompok ....", options: ["formal", "sekunder", "informal", "okupasional"], answer: 2, solution: "1. Kelompok informal terbentuk secara spontan atas dasar keakraban tanpa aturan tertulis. 2. Arisan ibu-ibu RT terbentuk dari hubungan akrab antar tetangga. 3. Kelompok formal justru memiliki struktur dan aturan resmi seperti OSIS. Jadi, jawaban yang tepat adalah informal." },
  { q: "Ikatan Dokter Indonesia (IDI) dan Persatuan Guru Republik Indonesia (PGRI) termasuk kelompok ....", options: ["okupasional", "volunter", "kekerabatan", "paguyuban"], answer: 0, solution: "1. Kelompok okupasional adalah kelompok yang anggotanya memiliki kesamaan pekerjaan atau profesi. 2. IDI beranggotakan para dokter, sedangkan PGRI beranggotakan para guru. 3. Kelompok volunter justru beranggotakan relawan tanpa memandang profesi. Jadi, jawaban yang tepat adalah okupasional." },
  { q: "Sekelompok pemuda yang secara sukarela membantu korban bencana alam tanpa mengharap imbalan termasuk kelompok ....", options: ["formal", "okupasional", "primer", "volunter"], answer: 3, solution: "1. Kelompok volunter adalah kelompok yang terbentuk atas dasar kesukarelaan anggotanya. 2. Para pemuda membantu korban bencana tanpa mengharap imbalan. 3. Kelompok okupasional didasarkan pada kesamaan profesi, bukan kesukarelaan. Jadi, jawaban yang tepat adalah volunter." },
  { q: "Perbedaan kelompok formal dan informal terletak pada ....", options: ["kelompok formal anggotanya sedikit, sedangkan informal anggotanya banyak", "kelompok formal tidak memiliki tujuan, sedangkan informal memiliki tujuan", "kelompok formal memiliki aturan tertulis dan struktur resmi, sedangkan informal terbentuk spontan atas dasar keakraban", "keduanya sama-sama tidak memiliki aturan"], answer: 2, solution: "1. Kelompok formal memiliki ciri aturan tertulis, struktur organisasi, dan tujuan yang jelas. 2. Kelompok informal terbentuk secara spontan atas dasar keakraban tanpa aturan tertulis. 3. Jadi pembedanya adalah ada tidaknya aturan tertulis dan struktur resmi. Jadi, jawaban yang tepat adalah pernyataan ketiga." },
  { q: "Sekelompok kecil siswa yang sangat akrab, cenderung eksklusif, dan sulit menerima anggota baru disebut ....", options: ["klik", "gang", "massa", "publik"], answer: 0, solution: "1. Klik (clique) adalah kelompok kecil yang sangat akrab dan bersifat eksklusif. 2. Kelompok tersebut sulit menerima anggota baru dari luar. 3. Gang adalah kelompok sebaya yang lebih terbuka, sedangkan massa berkumpul sesaat. Jadi, jawaban yang tepat adalah klik." },
  { q: "Kelompok remaja sebaya yang terbentuk secara spontan untuk berkumpul bersama dan memiliki solidaritas kuat disebut ....", options: ["klik", "publik", "massa", "gang"], answer: 3, solution: "1. Gang adalah kelompok sebaya yang terbentuk secara spontan dengan solidaritas yang kuat. 2. Kelompok remaja tersebut berkumpul bersama atas dasar kesamaan usia dan kepentingan. 3. Klik lebih kecil dan eksklusif, sedangkan gang lebih terbuka. Jadi, jawaban yang tepat adalah gang." },
  { q: "Sekumpulan orang yang tidak berinteraksi langsung tetapi memiliki perhatian yang sama terhadap suatu isu melalui media massa disebut ....", options: ["massa", "publik", "kerumunan", "gang"], answer: 1, solution: "1. Publik adalah kumpulan orang yang tidak berinteraksi langsung tetapi dihubungkan oleh media. 2. Mereka memiliki perhatian yang sama terhadap suatu isu, misalnya pembaca berita yang sama. 3. Massa justru berkumpul secara fisik di suatu tempat. Jadi, jawaban yang tepat adalah publik." },
  { q: "Ribuan orang berkumpul di lapangan untuk mengikuti aksi demonstrasi. Kumpulan orang tersebut disebut ....", options: ["publik", "kerumunan panik", "massa", "klik"], answer: 2, solution: "1. Massa adalah kumpulan orang yang berkumpul secara fisik dalam waktu dan tempat tertentu dengan tujuan tertentu. 2. Ribuan orang berkumpul di lapangan untuk berdemonstrasi. 3. Publik tidak berkumpul fisik, sedangkan kerumunan panik terjadi karena bahaya. Jadi, jawaban yang tepat adalah massa." },
  { q: "Perbedaan publik dan massa adalah ....", options: ["publik tidak berkumpul secara fisik dan dihubungkan oleh media, sedangkan massa berkumpul secara fisik di suatu tempat", "publik selalu berkumpul, sedangkan massa tidak pernah berkumpul", "publik bersifat sementara, sedangkan massa bersifat permanen", "keduanya tidak memiliki perbedaan"], answer: 0, solution: "1. Publik adalah kumpulan orang yang tidak berinteraksi langsung dan dihubungkan oleh media massa. 2. Massa adalah kumpulan orang yang berkumpul secara fisik di suatu tempat dan waktu. 3. Jadi pembedanya adalah berkumpul fisik atau tidak. Jadi, jawaban yang tepat adalah pernyataan pertama." },
  { q: "Para peserta seminar yang duduk tertib mendengarkan pembicara termasuk kerumunan ....", options: ["tidak formal", "panik", "immoral", "formal"], answer: 3, solution: "1. Kerumunan formal (audiens) adalah kerumunan yang terorganisasi dengan tujuan yang jelas. 2. Peserta seminar duduk tertib dengan tujuan mendengarkan pembicara. 3. Kerumunan tidak formal justru spontan tanpa tujuan jelas. Jadi, jawaban yang tepat adalah formal." },
  { q: "Orang-orang yang berkerumun melihat kecelakaan lalu lintas di jalan termasuk kerumunan ....", options: ["formal", "panik", "tidak formal", "immoral"], answer: 2, solution: "1. Kerumunan tidak formal (penonton kasual) adalah kerumunan spontan tanpa organisasi dan tujuan yang jelas. 2. Orang-orang berkerumun melihat kecelakaan secara spontan dan sementara. 3. Kerumunan formal justru terorganisasi seperti peserta seminar. Jadi, jawaban yang tepat adalah tidak formal." },
  { q: "Penonton bioskop yang berlarian menyelamatkan diri ketika terjadi kebakaran termasuk kerumunan ....", options: ["panik", "formal", "immoral", "kasual"], answer: 0, solution: "1. Kerumunan panik terjadi ketika orang-orang bertindak kalut untuk menyelamatkan diri dari bahaya. 2. Penonton berlarian karena kebakaran yang mengancam keselamatan. 3. Kerumunan immoral justru melanggar norma, bukan menyelamatkan diri. Jadi, jawaban yang tepat adalah panik." },
  { q: "Massa yang bertindak anarkis dan melanggar norma-norma masyarakat saat berdemonstrasi termasuk kerumunan ....", options: ["formal", "panik", "kasual", "immoral"], answer: 3, solution: "1. Kerumunan immoral adalah kerumunan yang bertindak melanggar norma dan hukum. 2. Massa anarkis merusak dan melanggar norma masyarakat. 3. Kerumunan panik bertindak kalut karena bahaya, bukan karena melanggar norma. Jadi, jawaban yang tepat adalah immoral." },
  { q: "Ciri birokrasi menurut Max Weber adalah ....", options: ["hubungan akrab dan kekeluargaan antarpegawai", "pembagian kerja yang jelas, hierarki wewenang, aturan tertulis, dan hubungan impersonal", "keputusan diambil secara spontan tanpa aturan", "promosi jabatan berdasarkan hubungan kekerabatan"], answer: 1, solution: "1. Menurut Max Weber, birokrasi yang ideal memiliki pembagian kerja yang jelas. 2. Selain itu ada hierarki wewenang, aturan formal tertulis, dan hubungan kerja yang impersonal. 3. Promosi didasarkan pada prestasi, bukan kekerabatan atau keakraban. Jadi, jawaban yang tepat adalah pernyataan kedua." },
  { q: "Kantor kelurahan yang melayani warga dengan prosedur tertulis dan pembagian tugas yang jelas menerapkan ....", options: ["kepemimpinan laissez-faire", "sistem kekerabatan", "birokrasi", "paguyuban"], answer: 2, solution: "1. Birokrasi adalah sistem organisasi yang bekerja berdasarkan aturan tertulis dan pembagian tugas yang jelas. 2. Kantor kelurahan melayani dengan prosedur tertulis dan tugas yang terbagi. 3. Paguyuban justru berlandaskan keakraban, bukan prosedur tertulis. Jadi, jawaban yang tepat adalah birokrasi." },
  { q: "Seorang anak merasa disayangi dan diperhatikan dalam keluarganya. Hal tersebut menunjukkan fungsi kelompok sebagai ....", options: ["pemberi afeksi", "sarana mencapai tujuan", "alat pengawasan", "sumber tekanan"], answer: 0, solution: "1. Fungsi afeksi adalah fungsi kelompok dalam memberikan kasih sayang kepada anggotanya. 2. Anak merasa disayangi dan diperhatikan dalam keluarga. 3. Fungsi sarana mencapai tujuan berkaitan dengan pemenuhan kebutuhan materiil, bukan kasih sayang. Jadi, jawaban yang tepat adalah pemberi afeksi." },
  { q: "Para petani bergabung dalam kelompok tani agar lebih mudah memperoleh pupuk bersubsidi. Hal tersebut menunjukkan fungsi kelompok sebagai ....", options: ["pemberi afeksi", "alat rekreasi", "sumber konflik", "sarana mencapai tujuan"], answer: 3, solution: "1. Fungsi kelompok sebagai sarana mencapai tujuan berarti kelompok membantu anggota memenuhi kebutuhan dan keinginannya. 2. Petani bergabung agar lebih mudah memperoleh pupuk bersubsidi. 3. Fungsi afeksi berkaitan dengan kasih sayang, bukan kebutuhan materiil. Jadi, jawaban yang tepat adalah sarana mencapai tujuan." },
  { q: "Anggota kelompok belajar saling mengingatkan agar tidak mencontek saat ujian. Hal tersebut menunjukkan fungsi kelompok sebagai ....", options: ["pemberi afeksi", "sarana hiburan", "alat pengawasan dan tekanan sosial", "sumber perpecahan"], answer: 2, solution: "1. Fungsi kelompok sebagai tekanan berarti kelompok mengawasi perilaku anggotanya agar sesuai norma. 2. Anggota saling mengingatkan agar tidak mencontek. 3. Pengawasan tersebut adalah bentuk kontrol sosial dalam kelompok. Jadi, jawaban yang tepat adalah alat pengawasan dan tekanan sosial." },
  { q: "Seorang ketua kelas yang mengambil semua keputusan sendiri tanpa bermusyawarah menerapkan gaya kepemimpinan ....", options: ["otoriter", "demokratis", "laissez-faire", "partisipatif"], answer: 0, solution: "1. Kepemimpinan otoriter adalah gaya pemimpin yang mengambil keputusan sepihak tanpa melibatkan anggota. 2. Ketua kelas tersebut memutuskan sendiri tanpa musyawarah. 3. Kepemimpinan demokratis justru mengutamakan musyawarah. Jadi, jawaban yang tepat adalah otoriter." },
  { q: "Ketua OSIS yang selalu bermusyawarah dengan pengurus sebelum mengambil keputusan menerapkan gaya kepemimpinan ....", options: ["otoriter", "laissez-faire", "bebas mutlak", "demokratis"], answer: 3, solution: "1. Kepemimpinan demokratis adalah gaya pemimpin yang melibatkan anggota dalam pengambilan keputusan. 2. Ketua OSIS selalu bermusyawarah dengan pengurus sebelum memutuskan. 3. Kepemimpinan otoriter justru memutuskan sepihak tanpa musyawarah. Jadi, jawaban yang tepat adalah demokratis." },
  { q: "Seorang pemimpin yang membiarkan anggotanya bekerja bebas tanpa banyak pengawasan menerapkan gaya kepemimpinan ....", options: ["otoriter", "laissez-faire", "demokratis", "karismatik"], answer: 1, solution: "1. Kepemimpinan laissez-faire adalah gaya pemimpin yang memberi kebebasan penuh kepada anggota. 2. Pemimpin tersebut tidak banyak mengawasi dan membiarkan anggota bekerja sendiri. 3. Kepemimpinan otoriter justru mengawasi ketat dan memutuskan sepihak. Jadi, jawaban yang tepat adalah laissez-faire." },
  { q: "Seorang siswa memakai seragam sesuai aturan sekolah karena mengikuti kebiasaan teman-temannya. Perilaku tersebut disebut ....", options: ["kohesi", "deviasi", "konformitas", "apatisme"], answer: 2, solution: "1. Konformitas adalah penyesuaian perilaku individu dengan norma atau kebiasaan kelompoknya. 2. Siswa tersebut menyesuaikan diri memakai seragam seperti teman-temannya. 3. Deviasi justru penyimpangan dari norma, bukan penyesuaian. Jadi, jawaban yang tepat adalah konformitas." },
  { q: "Tim futsal yang anggotanya saling mendukung dan enggan keluar dari tim menunjukkan tingginya ....", options: ["kohesi kelompok", "konflik kelompok", "apatisme anggota", "individualisme"], answer: 0, solution: "1. Kohesi kelompok adalah daya tarik dan ikatan yang membuat anggota bertahan dalam kelompok. 2. Anggota tim saling mendukung dan tidak ingin keluar dari tim. 3. Hal tersebut menunjukkan ikatan kelompok yang kuat, bukan konflik. Jadi, jawaban yang tepat adalah kohesi kelompok." },
  { q: "Aturan tidak tertulis yang disepakati anggota kelompok dan menjadi pedoman perilaku mereka disebut ....", options: ["adat istiadat", "hukum formal", "perintah pemimpin", "norma kelompok"], answer: 3, solution: "1. Norma kelompok adalah aturan yang disepakati anggota kelompok sebagai pedoman berperilaku. 2. Aturan tersebut tidak tertulis tetapi dipatuhi bersama. 3. Hukum formal justru tertulis dan dibuat oleh lembaga resmi. Jadi, jawaban yang tepat adalah norma kelompok." },
  { q: "Dalam kelompok belajar, Ani bertugas mencatat materi sedangkan Budi bertugas mempresentasikan. Pembagian tugas tersebut berkaitan dengan ....", options: ["status ekonomi", "kepribadian", "peran dalam kelompok", "stratifikasi"], answer: 2, solution: "1. Peran adalah pelaksanaan tugas dan kewajiban sesuai kedudukan dalam kelompok. 2. Ani dan Budi menjalankan tugas masing-masing dalam kelompok belajar. 3. Pembagian tugas tersebut adalah wujud peran, bukan status ekonomi. Jadi, jawaban yang tepat adalah peran dalam kelompok." },
  { q: "Karang taruna di suatu desa termasuk contoh kelompok sosial yang bersifat ....", options: ["informal tanpa struktur", "formal karena memiliki struktur pengurus dan aturan organisasi", "kerumunan sesaat", "massa yang sementara"], answer: 1, solution: "1. Kelompok formal memiliki struktur organisasi, aturan, dan tujuan yang jelas. 2. Karang taruna memiliki susunan pengurus dan aturan organisasi kepemudaan desa. 3. Kerumunan dan massa hanya berkumpul sesaat tanpa struktur. Jadi, jawaban yang tepat adalah formal karena memiliki struktur pengurus dan aturan organisasi." },
  { q: "Koperasi simpan pinjam yang anggotanya terikat aturan tertulis untuk mencapai kesejahteraan bersama termasuk kelompok ....", options: ["formal", "informal", "kerumunan", "publik"], answer: 0, solution: "1. Kelompok formal memiliki aturan tertulis dan tujuan yang jelas. 2. Koperasi memiliki anggaran dasar dan aturan yang mengikat anggotanya. 3. Kelompok informal justru terbentuk spontan tanpa aturan tertulis. Jadi, jawaban yang tepat adalah formal." },
  { q: "Ciri utama organisasi formal adalah ....", options: ["terbentuk secara spontan", "berlandaskan keakraban semata", "tanpa pembagian tugas", "memiliki tujuan jelas, aturan tertulis, dan struktur organisasi"], answer: 3, solution: "1. Organisasi formal adalah kelompok yang dibentuk secara resmi dengan tujuan tertentu. 2. Ciri-cirinya adalah tujuan yang jelas, aturan tertulis, dan struktur organisasi. 3. Terbentuk spontan dan berlandaskan keakraban adalah ciri kelompok informal. Jadi, jawaban yang tepat adalah pernyataan keempat." },
  { q: "Kedudukan seseorang sebagai ketua OSIS dalam struktur organisasi sekolah disebut ....", options: ["peran", "kepribadian", "status", "fungsi"], answer: 2, solution: "1. Status adalah kedudukan seseorang dalam masyarakat atau kelompok. 2. Jabatan ketua OSIS adalah kedudukan dalam struktur organisasi sekolah. 3. Peran adalah pelaksanaan tugas dari kedudukan tersebut, misalnya memimpin rapat. Jadi, jawaban yang tepat adalah status." },
  { q: "Hubungan antaranggota keluarga yang bersifat pribadi dan akrab berbeda dengan hubungan antaranggota partai politik yang bersifat formal dan bertujuan tertentu. Perbedaan tersebut menunjukkan klasifikasi kelompok menurut Cooley, yaitu kelompok ....", options: ["paguyuban dan patembayan", "primer dan sekunder", "formal dan informal", "in-group dan out-group"], answer: 1, solution: "1. Menurut Cooley, kelompok primer memiliki hubungan yang pribadi, akrab, dan langgeng seperti keluarga. 2. Kelompok sekunder memiliki hubungan yang formal dan berorientasi tujuan seperti partai politik. 3. Paguyuban dan patembayan adalah klasifikasi menurut Tonnies, bukan Cooley. Jadi, jawaban yang tepat adalah primer dan sekunder." },
  { q: "Perubahan yang terjadi dalam kelompok, seperti pergantian kepemimpinan dan penyesuaian norma, disebut ....", options: ["dinamika kelompok", "disorganisasi kelompok", "apatisme kelompok", "stagnasi kelompok"], answer: 0, solution: "1. Dinamika kelompok adalah perubahan dan gerak yang terjadi dalam kelompok. 2. Pergantian kepemimpinan dan penyesuaian norma adalah contoh perubahan tersebut. 3. Disorganisasi justru berarti keretakan, bukan perubahan yang wajar. Jadi, jawaban yang tepat adalah dinamika kelompok." },
  { q: "Warga desa yang hidup rukun atas dasar kekeluargaan berbeda dengan karyawan perusahaan yang terikat kontrak kerja. Perbandingan tersebut menggambarkan perbedaan ....", options: ["kelompok primer dan sekunder", "in-group dan out-group", "massa dan publik", "gemeinschaft dan gesellschaft"], answer: 3, solution: "1. Gemeinschaft (paguyuban) adalah ikatan sosial atas dasar kekeluargaan dan keakraban. 2. Gesellschaft (patembayan) adalah ikatan sosial atas dasar kontrak dan tujuan tertentu. 3. Perbandingan warga desa dan karyawan perusahaan tepat menggambarkan keduanya. Jadi, jawaban yang tepat adalah gemeinschaft dan gesellschaft." },
  { q: "Warga yang rutin mengikuti kerja bakti membersihkan lingkungan menunjukkan kelompok sosial yang terbentuk atas dasar ....", options: ["paksaan penguasa", "kepentingan ekonomi semata", "hubungan darah", "kepentingan dan tujuan bersama"], answer: 3, solution: "1. Kelompok sosial terbentuk karena ada faktor pengikat antaranggota. 2. Warga mengikuti kerja bakti karena memiliki kepentingan dan tujuan bersama, yaitu lingkungan yang bersih. 3. Kerja bakti dilakukan sukarela, bukan karena paksaan penguasa. Jadi, jawaban yang tepat adalah kepentingan dan tujuan bersama." },
{ q: "Seseorang yang lahir di kasta rendah hampir tidak mungkin pindah ke kasta lain sepanjang hidupnya. Keadaan ini menunjukkan stratifikasi yang bersifat ....", options: ["tertutup", "terbuka", "campuran", "horizontal"], answer: 0, solution: "1. Stratifikasi tertutup adalah pelapisan yang tidak memungkinkan perpindahan antarlapisan. 2. Pada sistem kasta kedudukan ditentukan oleh kelahiran sehingga anggotanya sulit berpindah. 3. Jadi sistem tersebut bersifat tertutup." },
  { q: "Dalam masyarakat dengan stratifikasi terbuka, kedudukan sosial seseorang terutama ditentukan oleh ....", options: ["keturunan dan kasta", "usaha dan prestasi sendiri", "jenis kelamin", "kekayaan orang tua"], answer: 1, solution: "1. Stratifikasi terbuka memberi kesempatan setiap orang berpindah lapisan. 2. Perpindahan itu dimungkinkan melalui usaha dan prestasi sendiri, bukan kelahiran. 3. Jadi jawabannya adalah usaha dan prestasi sendiri." },
  { q: "Sistem pelapisan yang memadukan unsur tertutup dan terbuka, misalnya masyarakat berkasta yang memberi peluang naik melalui pendidikan, disebut stratifikasi ....", options: ["horizontal", "vertikal", "campuran", "diferensiasi"], answer: 2, solution: "1. Stratifikasi campuran menggabungkan ciri tertutup dan terbuka. 2. Contohnya masyarakat yang mengenal kasta tetapi membuka peluang prestasi lewat pendidikan. 3. Jadi disebut stratifikasi campuran." },
  { q: "Menurut Max Weber, pelapisan sosial dalam masyarakat didasarkan pada kekayaan, kekuasaan, kehormatan, dan ....", options: ["keturunan", "jenis kelamin", "ras", "ilmu pengetahuan"], answer: 3, solution: "1. Max Weber menyebutkan dasar pelapisan sosial meliputi dimensi ekonomi, kekuasaan, dan prestise. 2. Dalam sosiologi SMA keempat dasar itu dirumuskan sebagai kekayaan, kekuasaan, kehormatan, dan ilmu pengetahuan. 3. Jadi jawaban yang tepat adalah ilmu pengetahuan." },
  { q: "Pengusaha kaya pemilik banyak perusahaan dan buruh harian lepas menunjukkan pelapisan masyarakat berdasarkan ukuran ....", options: ["ekonomi", "politik", "sosial", "budaya"], answer: 0, solution: "1. Ukuran ekonomi melihat kepemilikan harta dan penghasilan. 2. Perbedaan pengusaha kaya dan buruh harian lepas tampak dari sisi ekonominya. 3. Jadi pelapisan tersebut berdasarkan ukuran ekonomi." },
  { q: "Perbedaan kedudukan antara pejabat negara dan rakyat biasa menunjukkan pelapisan berdasarkan kriteria ....", options: ["ekonomi", "sosial", "politik", "pendidikan"], answer: 2, solution: "1. Kriteria politik mendasarkan pelapisan pada kekuasaan dan jabatan. 2. Pejabat negara memiliki kekuasaan formal sedangkan rakyat biasa tidak. 3. Jadi pelapisannya berdasarkan kriteria politik." },
  { q: "Perbedaan warna kulit dan bentuk rambut yang diturunkan secara biologis antarkelompok manusia disebut diferensiasi ....", options: ["etnis", "ras", "agama", "gender"], answer: 1, solution: "1. Ras adalah penggolongan berdasarkan ciri fisik yang diwariskan secara biologis. 2. Warna kulit dan bentuk rambut termasuk ciri fisik tersebut. 3. Jadi disebut diferensiasi ras." },
  { q: "Suku Batak, Jawa, dan Dayak yang memiliki bahasa dan adat istiadat berbeda merupakan diferensiasi berdasarkan ....", options: ["ras", "profesi", "suku bangsa atau etnis", "kelas sosial"], answer: 2, solution: "1. Etnis atau suku bangsa dibedakan oleh bahasa, adat, dan asal-usul yang sama. 2. Batak, Jawa, dan Dayak memenuhi ciri tersebut. 3. Jadi diferensiasinya berdasarkan suku bangsa atau etnis." },
  { q: "Umat Islam, Kristen, Hindu, dan Buddha hidup berdampingan tanpa tingkatan tinggi-rendah. Perbedaan tersebut termasuk diferensiasi berdasarkan ....", options: ["ras", "strata", "gender", "agama"], answer: 3, solution: "1. Diferensiasi adalah perbedaan horizontal yang tidak menunjukkan tingkatan. 2. Perbedaan keyakinan antarumat beragama bersifat sejajar, bukan vertikal. 3. Jadi termasuk diferensiasi berdasarkan agama." },
  { q: "Anggapan bahwa mengasuh anak adalah tugas perempuan sedangkan mencari nafkah tugas laki-laki merupakan diferensiasi berdasarkan ....", options: ["jenis kelamin atau gender", "ras", "profesi", "etnis"], answer: 0, solution: "1. Gender adalah pembedaan peran sosial antara laki-laki dan perempuan yang dibentuk masyarakat. 2. Anggapan tentang tugas mengasuh dan mencari nafkah adalah peran yang dikonstruksi sosial. 3. Jadi termasuk diferensiasi berdasarkan jenis kelamin atau gender." },
  { q: "Salah satu fungsi stratifikasi sosial adalah mengatur distribusi hak dan kewajiban. Artinya ....", options: ["setiap lapisan memiliki hak dan kewajiban yang berbeda sesuai kedudukannya", "semua orang memiliki hak dan kewajiban yang persis sama", "lapisan atas bebas dari segala kewajiban", "lapisan bawah tidak memiliki hak apa pun"], answer: 0, solution: "1. Fungsi stratifikasi adalah menempatkan hak dan kewajiban sesuai kedudukan tiap lapisan. 2. Misalnya pejabat berhak memerintah tetapi berkewajiban melayani masyarakat. 3. Jadi setiap lapisan memiliki hak dan kewajiban berbeda sesuai kedudukannya." },
  { q: "Berikut ini yang bukan merupakan fungsi stratifikasi sosial adalah ....", options: ["mengatur distribusi hak dan kewajiban", "memupuk solidaritas antaranggota masyarakat", "mendorong persaingan yang sehat", "menghapus seluruh perbedaan antarkelompok masyarakat"], answer: 3, solution: "1. Fungsi stratifikasi antara lain distribusi hak dan kewajiban, solidaritas, serta kontrol sosial. 2. Stratifikasi justru mengakui adanya perbedaan lapisan, bukan menghapuskannya. 3. Jadi menghapus seluruh perbedaan bukan fungsi stratifikasi." },
  { q: "Menurut Karl Marx, golongan pemilik modal dan alat produksi yang memperkerjakan orang lain disebut kelas ....", options: ["proletar", "menengah", "pekerja", "borjuis"], answer: 3, solution: "1. Marx membagi masyarakat kapitalis menjadi dua kelas utama. 2. Kelas pemilik modal dan alat produksi yang mempekerjakan buruh disebut borjuis. 3. Jadi jawabannya adalah kelas borjuis." },
  { q: "Menurut Karl Marx, konflik kelas dalam masyarakat kapitalis terjadi karena ....", options: ["perbedaan agama antarkelas", "kepentingan ekonomi borjuis dan proletar yang bertolak belakang", "perbedaan suku bangsa", "persaingan memperebutkan jabatan politik"], answer: 1, solution: "1. Borjuis ingin keuntungan sebesar-besarnya sedangkan proletar ingin upah layak. 2. Kedua kepentingan ekonomi itu bertolak belakang sehingga menimbulkan pertentangan. 3. Jadi konflik kelas terjadi karena kepentingan ekonomi yang bertolak belakang." },
  { q: "Kedudukan bangsawan yang diperoleh seseorang karena kelahirannya disebut status ....", options: ["ascribed", "achieved", "assigned", "aktual"], answer: 0, solution: "1. Status ascribed adalah kedudukan yang diperoleh tanpa usaha, misalnya karena kelahiran. 2. Gelar bangsawan yang diwarisi orang tua termasuk di dalamnya. 3. Jadi disebut status ascribed." },
  { q: "Seseorang menjadi dokter setelah menempuh pendidikan kedokteran bertahun-tahun. Status yang diperoleh melalui usaha tersebut disebut status ....", options: ["ascribed", "assigned", "achieved", "otomatis"], answer: 2, solution: "1. Status achieved diperoleh melalui usaha dan prestasi sendiri. 2. Menjadi dokter memerlukan pendidikan dan kerja keras bertahun-tahun. 3. Jadi disebut status achieved." },
  { q: "Gelar Pahlawan Nasional yang diberikan negara atas jasa seseorang merupakan contoh status ....", options: ["ascribed", "primer", "achieved", "assigned"], answer: 3, solution: "1. Status assigned adalah kedudukan yang diberikan oleh pihak lain sebagai penghargaan. 2. Gelar Pahlawan Nasional diberikan negara atas jasa, bukan diperoleh sejak lahir atau murni usaha sendiri. 3. Jadi termasuk status assigned." },
  { q: "Mobil mewah dan rumah besar sering dipakai untuk menunjukkan kedudukan pemiliknya di masyarakat. Benda-benda tersebut berfungsi sebagai ....", options: ["simbol status", "alat produksi", "norma sosial", "modal sosial"], answer: 0, solution: "1. Simbol status adalah tanda lahiriah yang menunjukkan kedudukan seseorang. 2. Mobil mewah dan rumah besar menjadi penanda kekayaan dan gengsi pemiliknya. 3. Jadi benda tersebut berfungsi sebagai simbol status." },
  { q: "Kemiskinan yang disebabkan oleh sikap masyarakatnya sendiri, seperti malas bekerja dan mudah menyerah, disebut kemiskinan ....", options: ["struktural", "kultural", "absolut", "relatif"], answer: 1, solution: "1. Kemiskinan kultural bersumber dari nilai dan perilaku budaya masyarakat. 2. Sikap malas dan mudah menyerah adalah faktor budaya, bukan struktur. 3. Jadi disebut kemiskinan kultural." },
  { q: "Kemiskinan yang terjadi karena sulitnya akses pendidikan dan modal akibat struktur masyarakat yang tidak adil disebut kemiskinan ....", options: ["kultural", "individual", "struktural", "musiman"], answer: 2, solution: "1. Kemiskinan struktural disebabkan oleh ketimpangan struktur sosial. 2. Sulitnya akses pendidikan dan modal bagi si miskin adalah masalah struktural. 3. Jadi disebut kemiskinan struktural." },
  { q: "Kesenjangan antara warga kota besar yang serba berkecukupan dan warga daerah terpencil yang serba kekurangan mencerminkan ketimpangan dalam hal ....", options: ["jumlah penduduk", "luas wilayah", "jumlah suku bangsa", "akses terhadap sumber daya dan kesempatan"], answer: 3, solution: "1. Kesenjangan sosial adalah perbedaan akses terhadap sumber daya antar kelompok. 2. Warga kota mudah memperoleh fasilitas sedangkan warga terpencil sulit. 3. Jadi ketimpangannya dalam akses terhadap sumber daya dan kesempatan." },
  { q: "Keadilan sosial dalam masyarakat dapat diwujudkan melalui ....", options: ["penghapusan seluruh perbedaan individu", "pemberian kesempatan yang sama untuk mengembangkan diri", "pembatasan kekayaan semua warga", "penyeragaman profesi masyarakat"], answer: 1, solution: "1. Keadilan sosial berarti setiap warga memperoleh perlakuan dan kesempatan yang adil. 2. Memberi kesempatan yang sama untuk berkembang adalah wujudnya. 3. Jadi jawabannya pemberian kesempatan yang sama untuk mengembangkan diri." },
  { q: "Pada masyarakat berkasta, anak dari kasta rendah hampir mustahil naik ke kasta tinggi karena ....", options: ["tidak ada sekolah di masyarakatnya", "stratifikasinya bersifat tertutup dan ditentukan oleh kelahiran", "mereka tidak memiliki cita-cita", "pemerintah melarang semua pendidikan"], answer: 1, solution: "1. Stratifikasi tertutup tidak memberi peluang berpindah lapisan. 2. Pada sistem kasta kedudukan ditentukan oleh kelahiran sejak lahir. 3. Jadi anak kasta rendah hampir mustahil naik kasta." },
  { q: "Pengelompokan berdasarkan agama yang tidak menunjukkan tingkatan, berbeda dengan pengelompokan berdasarkan kekayaan yang menunjukkan tingkatan, adalah contoh perbedaan antara ....", options: ["mobilitas naik dan turun", "status ascribed dan achieved", "diferensiasi dan stratifikasi", "stratifikasi vertikal dan horizontal"], answer: 2, solution: "1. Diferensiasi adalah perbedaan horizontal tanpa tingkatan seperti perbedaan agama. 2. Stratifikasi adalah perbedaan vertikal bertingkat seperti perbedaan kekayaan. 3. Jadi contoh tersebut menunjukkan perbedaan diferensiasi dan stratifikasi." },
  { q: "Perpindahan kedudukan seseorang atau kelompok dari satu lapisan sosial ke lapisan sosial lain disebut ....", options: ["mobilitas sosial", "mobilitas geografis", "migrasi penduduk", "urbanisasi"], answer: 0, solution: "1. Mobilitas sosial adalah gerak perpindahan status atau kedudukan sosial. 2. Perpindahan antarlapisan sosial sesuai dengan pengertian itu. 3. Jadi disebut mobilitas sosial." },
  { q: "Seorang buruh pabrik membuka usaha sendiri hingga menjadi pengusaha sukses. Peristiwa tersebut merupakan mobilitas ....", options: ["horizontal", "lateral", "vertikal ke atas atau social climbing", "vertikal ke bawah"], answer: 2, solution: "1. Mobilitas vertikal ke atas terjadi saat status seseorang naik ke lapisan lebih tinggi. 2. Buruh yang menjadi pengusaha sukses mengalami kenaikan status. 3. Jadi termasuk mobilitas vertikal ke atas atau social climbing." },
  { q: "Seorang pejabat yang dipecat karena korupsi akhirnya menjadi pengangguran. Peristiwa tersebut merupakan contoh ....", options: ["konflik pribadi", "social sinking", "social climbing", "mobilitas horizontal"], answer: 1, solution: "1. Social sinking adalah mobilitas vertikal ke bawah menuju status lebih rendah. 2. Pejabat yang dipecat lalu menganggur mengalami penurunan status. 3. Jadi peristiwa itu contoh social sinking." },
  { q: "Seorang manajer pemasaran dirotasi menjadi manajer personalia dengan gaji dan tunjangan yang sama. Perpindahan tersebut termasuk mobilitas ....", options: ["vertikal ke atas", "horizontal", "vertikal ke bawah", "antargenerasi"], answer: 1, solution: "1. Mobilitas horizontal adalah perpindahan sederajat tanpa perubahan tingkatan. 2. Rotasi antarjabatan setara tidak menaikkan atau menurunkan status. 3. Jadi termasuk mobilitas horizontal." },
  { q: "Kakek seorang nelayan dan ayah seorang buruh pelabuhan, sedangkan cucunya menjadi pengusaha perikanan yang sukses. Jika status cucu dibandingkan dengan kakeknya, terjadi mobilitas ....", options: ["intragenerasi", "horizontal", "antargenerasi", "geografis"], answer: 2, solution: "1. Mobilitas antargenerasi membandingkan status antar dua generasi atau lebih. 2. Di sini status cucu dibandingkan dengan kakeknya yang berbeda generasi. 3. Jadi terjadi mobilitas antargenerasi." },
  { q: "Seorang pedagang kaki lima bekerja keras hingga dalam masa hidupnya berhasil memiliki toko besar. Perubahan status dalam satu generasi tersebut disebut mobilitas ....", options: ["antargenerasi", "geografis", "horizontal", "intragenerasi"], answer: 3, solution: "1. Mobilitas intragenerasi adalah perubahan status dalam satu generasi atau masa hidup sendiri. 2. Pedagang itu naik status dalam hidupnya sendiri, bukan dibanding orang tuanya. 3. Jadi disebut mobilitas intragenerasi." },
  { q: "Seorang aktivis partai yang loyal akhirnya diangkat menjadi pejabat daerah. Saluran mobilitas sosial yang digunakannya adalah ....", options: ["pendidikan", "perkawinan", "militer", "organisasi politik"], answer: 3, solution: "1. Organisasi politik adalah salah satu saluran mobilitas sosial. 2. Aktivis yang menjadi pejabat naik status melalui jalur partai politik. 3. Jadi salurannya adalah organisasi politik." },
  { q: "Seseorang menikah dengan pasangan dari keluarga berada sehingga status sosialnya ikut naik. Saluran mobilitas tersebut adalah ....", options: ["pendidikan", "organisasi ekonomi", "perkawinan", "organisasi keagamaan"], answer: 2, solution: "1. Perkawinan termasuk saluran mobilitas sosial menurut Soekanto. 2. Menikah dengan keluarga berada dapat mengangkat status seseorang. 3. Jadi salurannya adalah perkawinan." },
  { q: "Seorang prajurit yang berprestasi naik pangkat hingga menjadi perwira tinggi. Saluran mobilitas sosial dalam peristiwa itu adalah ....", options: ["militer", "pendidikan", "perkawinan", "organisasi politik"], answer: 0, solution: "1. Militer adalah salah satu saluran mobilitas sosial. 2. Kenaikan pangkat prajurit terjadi melalui jalur kedinasan militer. 3. Jadi salurannya adalah militer." },
  { q: "Seorang karyawan koperasi yang rajin dan jujur akhirnya dipercaya menjadi pengusaha mitra koperasi. Saluran mobilitas tersebut adalah ....", options: ["organisasi politik", "organisasi keagamaan", "militer", "organisasi ekonomi"], answer: 3, solution: "1. Organisasi ekonomi seperti koperasi dan perusahaan adalah saluran mobilitas. 2. Karyawan yang naik menjadi pengusaha mitra bergerak lewat jalur ekonomi. 3. Jadi salurannya adalah organisasi ekonomi." },
  { q: "Seorang tokoh agama yang dihormati masyarakat diangkat menjadi pemimpin daerah. Saluran mobilitas yang berperan di sini adalah ....", options: ["organisasi keagamaan", "pendidikan", "perkawinan", "organisasi politik"], answer: 0, solution: "1. Organisasi keagamaan termasuk saluran mobilitas sosial. 2. Penghormatan sebagai tokoh agama mengangkatnya menjadi pemimpin daerah. 3. Jadi saluran yang berperan adalah organisasi keagamaan." },
  { q: "Industrialisasi membuka banyak lapangan kerja baru sehingga rakyat kecil berkesempatan naik status. Faktor pendorong mobilitas tersebut bersifat ....", options: ["individu", "struktural", "keberuntungan", "budaya"], answer: 1, solution: "1. Faktor struktural adalah dorongan dari struktur masyarakat seperti industrialisasi. 2. Terbukanya lapangan kerja baru adalah perubahan struktur ekonomi. 3. Jadi faktor pendorongnya bersifat struktural." },
  { q: "Seseorang berhasil naik jabatan karena memiliki keterampilan dan keahlian khusus. Faktor pendorong mobilitas tersebut berasal dari ....", options: ["keterampilan dan keahlian yang dimiliki", "struktur ekonomi", "keberuntungan", "diskriminasi"], answer: 0, solution: "1. Faktor individu adalah kualitas pribadi seperti pendidikan dan keterampilan. 2. Keterampilan khusus yang dimiliki adalah kualitas dirinya sendiri. 3. Jadi pendorongnya berasal dari keterampilan dan keahlian yang dimiliki." },
  { q: "Seorang petani menemukan harta peninggalan keluarganya lalu menjadi orang kaya. Faktor pendorong mobilitas dalam peristiwa itu adalah ....", options: ["usaha keras", "pendidikan tinggi", "keberuntungan", "jabatan politik"], answer: 2, solution: "1. Keberuntungan adalah faktor pendorong mobilitas yang tidak direncanakan. 2. Menemukan harta peninggalan adalah peristiwa kebetulan yang menaikkan status. 3. Jadi faktornya adalah keberuntungan." },
  { q: "Penerapan diskriminasi dalam penerimaan kerja membuat kelompok tertentu sulit naik status. Hal tersebut merupakan faktor ....", options: ["kemiskinan", "pendidikan", "urbanisasi", "penghambat mobilitas sosial"], answer: 3, solution: "1. Diskriminasi menutup kesempatan kelompok tertentu untuk berkembang. 2. Sesuatu yang menutup kesempatan naik status adalah penghambat mobilitas. 3. Jadi diskriminasi merupakan faktor penghambat mobilitas sosial." },
  { q: "Nilai feodal yang mengagungkan keturunan membuat rakyat biasa sulit mencapai kedudukan tinggi. Nilai tersebut merupakan faktor ....", options: ["pendorong mobilitas", "penghambat mobilitas sosial", "struktural positif", "keberuntungan"], answer: 1, solution: "1. Budaya feodal membatasi gerak rakyat biasa karena mengutamakan kelahiran. 2. Nilai yang membatasi kenaikan status adalah penghambat mobilitas. 3. Jadi nilai feodal merupakan faktor penghambat mobilitas sosial." },
  { q: "Terbukanya kesempatan mobilitas sosial mendorong setiap orang giat bekerja dan berprestasi. Hal ini merupakan dampak ....", options: ["positif mobilitas sosial", "negatif mobilitas sosial", "netral mobilitas sosial", "sampingan mobilitas sosial"], answer: 0, solution: "1. Dampak positif mobilitas adalah mendorong individu berprestasi. 2. Kesempatan naik status memotivasi orang bekerja lebih giat. 3. Jadi hal itu merupakan dampak positif mobilitas sosial." },
  { q: "Seseorang yang naik status terlalu cepat sering dilanda kecemasan takut kehilangan kedudukannya. Kondisi tersebut merupakan dampak ....", options: ["meningkatkan solidaritas keluarga", "memperluas kesempatan kerja", "negatif mobilitas sosial", "positif mobilitas sosial"], answer: 2, solution: "1. Dampak negatif mobilitas antara lain kecemasan status dan anomie. 2. Rasa takut kehilangan kedudukan adalah bentuk kecemasan status. 3. Jadi kondisi itu merupakan dampak negatif mobilitas sosial." },
  { q: "Perbedaan mobilitas geografis dan mobilitas sosial terletak pada ....", options: ["mobilitas geografis adalah perpindahan wilayah sedangkan mobilitas sosial adalah perpindahan status", "keduanya sama-sama perpindahan status sosial", "mobilitas geografis selalu menaikkan status", "mobilitas sosial hanya terjadi antar generasi"], answer: 0, solution: "1. Mobilitas geografis menyangkut perpindahan tempat atau wilayah. 2. Mobilitas sosial menyangkut perpindahan kedudukan atau status sosial. 3. Jadi perbedaannya adalah perpindahan wilayah berbanding perpindahan status." },
  { q: "Menurut Soerjono Soekanto, konflik adalah proses sosial antara dua orang atau lebih yang ....", options: ["berusaha menyingkirkan pihak lain dengan menghancurkan atau membuatnya tidak berdaya", "bekerja sama mencapai tujuan bersama", "menyesuaikan diri dengan norma baru", "berinteraksi tanpa tujuan yang jelas"], answer: 0, solution: "1. Soekanto merumuskan konflik sebagai usaha menyingkirkan pihak lawan. 2. Caranya dengan menghancurkan atau membuat lawan tidak berdaya. 3. Jadi konflik adalah proses sosial yang berusaha menyingkirkan pihak lain dengan menghancurkan atau membuatnya tidak berdaya." },
  { q: "Dua siswa berselisih paham hingga berkelahi karena masalah pribadi. Peristiwa tersebut termasuk konflik ....", options: ["rasial", "pribadi", "politik", "internasional"], answer: 1, solution: "1. Konflik pribadi terjadi antarindividu karena persoalan personal. 2. Perkelahian dua siswa berawal dari masalah pribadi keduanya. 3. Jadi termasuk konflik pribadi." },
  { q: "Bentrokan antara kelompok pendatang dan penduduk asli karena perbedaan suku termasuk konflik ....", options: ["pribadi", "antarkelas", "rasial", "politik"], answer: 2, solution: "1. Konflik rasial terjadi antarkelompok yang berbeda ras atau etnis. 2. Bentrokan pendatang dan penduduk asli berakar pada perbedaan kesukuan. 3. Jadi termasuk konflik rasial." },
  { q: "Persaingan antarpartai politik dalam memperebutkan kekuasaan pemerintahan termasuk konflik ....", options: ["rasial", "pribadi", "antarkelas", "politik"], answer: 3, solution: "1. Konflik politik berkaitan dengan perebutan kekuasaan. 2. Persaingan antarpartai memperebutkan pemerintahan adalah perebutan kekuasaan. 3. Jadi termasuk konflik politik." },
  { q: "Pertentangan antara direksi perusahaan dan serikat buruh mengenai kebijakan upah termasuk konflik ....", options: ["horizontal", "vertikal", "diagonal", "pribadi"], answer: 1, solution: "1. Konflik vertikal terjadi antara pihak yang berbeda tingkatan, seperti atasan dan bawahan. 2. Direksi dan buruh berada pada tingkatan yang berbeda dalam perusahaan. 3. Jadi termasuk konflik vertikal." },
  { q: "Tawuran antara warga dua kampung yang sederajat kedudukannya termasuk konflik ....", options: ["vertikal", "internasional", "horizontal", "rasial"], answer: 2, solution: "1. Konflik horizontal terjadi antara pihak-pihak yang sederajat. 2. Warga dua kampung memiliki kedudukan yang setara. 3. Jadi termasuk konflik horizontal." },
  { q: "Pendatang yang tidak memahami adat setempat sering bersitegang dengan penduduk asli. Faktor penyebab konflik tersebut adalah perbedaan ....", options: ["kepentingan", "kebudayaan", "individu", "perubahan sosial"], answer: 1, solution: "1. Perbedaan kebudayaan menimbulkan kesalahpahaman antarkelompok. 2. Ketidaktahuan pendatang terhadap adat setempat adalah perbedaan budaya. 3. Jadi faktornya adalah perbedaan kebudayaan." },
  { q: "Petani menolak kehadiran perusahaan tambang karena lahannya terancam digusur. Faktor penyebab konflik tersebut adalah perbedaan ....", options: ["kebudayaan", "individu", "kepentingan", "perubahan sosial"], answer: 2, solution: "1. Perbedaan kepentingan terjadi saat dua pihak menginginkan hal yang bertentangan. 2. Petani ingin mempertahankan lahan sedangkan perusahaan ingin menambang. 3. Jadi faktornya adalah perbedaan kepentingan." },
  { q: "Sebagian warga menolak pembangunan pabrik karena khawatir mengubah mata pencaharian mereka. Faktor penyebab konflik tersebut adalah ....", options: ["perbedaan individu", "perbedaan kebudayaan", "perbedaan kepentingan", "perubahan sosial"], answer: 3, solution: "1. Perubahan sosial yang cepat menimbulkan kegelisahan masyarakat. 2. Pembangunan pabrik mengubah tatanan dan mata pencaharian warga. 3. Jadi faktornya adalah perubahan sosial." },
  { q: "Dua tokoh masyarakat berselisih karena berbeda pendirian dan prinsip hidup. Faktor penyebab konflik tersebut adalah perbedaan ....", options: ["individu", "kebudayaan", "perubahan sosial", "kepentingan"], answer: 0, solution: "1. Perbedaan individu meliputi pendirian, perasaan, dan prinsip tiap orang. 2. Perselisihan dua tokoh berawal dari beda pendirian masing-masing. 3. Jadi faktornya adalah perbedaan individu." },
  { q: "Konflik berkepanjangan dapat meretakkan persatuan masyarakat. Akibat tersebut disebut ....", options: ["disintegrasi sosial", "solidaritas in-group", "munculnya norma baru", "meningkatnya toleransi"], answer: 0, solution: "1. Akibat negatif konflik adalah terpecahnya kesatuan masyarakat. 2. Retaknya persatuan akibat konflik disebut disintegrasi sosial. 3. Jadi akibat tersebut disebut disintegrasi sosial." },
  { q: "Ketika menghadapi ancaman dari luar, anggota suatu kelompok justru semakin kompak dan bersatu. Hal ini merupakan akibat ....", options: ["disintegrasi sosial", "korban jiwa dan harta", "positif konflik berupa menguatnya solidaritas in-group", "hilangnya norma lama"], answer: 2, solution: "1. Salah satu akibat positif konflik adalah memperkuat solidaritas kelompok sendiri. 2. Ancaman dari luar membuat anggota kelompok semakin kompak. 3. Jadi hal itu akibat positif konflik berupa menguatnya solidaritas in-group." },
  { q: "Kemiskinan yang diderita rakyat akibat kebijakan ekonomi yang tidak adil disebut kekerasan ....", options: ["fisik langsung", "struktural", "verbal", "simbolik"], answer: 1, solution: "1. Kekerasan struktural adalah kekerasan yang bersumber dari struktur sosial yang tidak adil. 2. Kebijakan ekonomi yang menyengsarakan rakyat adalah kekerasan lewat struktur. 3. Jadi disebut kekerasan struktural." },
  { q: "Dua pedagang pasar berselisih soal batas lapak lalu dipertemukan ketua paguyuban agar berunding dan menyelesaikan sendiri masalahnya. Cara penyelesaian tersebut disebut ....", options: ["konsiliasi", "mediasi", "arbitrasi", "ajudikasi"], answer: 0, solution: "1. Konsiliasi adalah mempertemukan pihak berselisih agar menyelesaikan sendiri. 2. Ketua paguyuban hanya mempertemukan tanpa ikut memutuskan. 3. Jadi cara tersebut disebut konsiliasi." },
  { q: "Kelompok tani yang berselisih soal jadwal air irigasi meminta saran penyuluh pertanian, tetapi keputusan akhir tetap di tangan kelompok tani. Cara penyelesaian tersebut disebut ....", options: ["konsiliasi", "arbitrasi", "mediasi", "ajudikasi"], answer: 2, solution: "1. Mediasi melibatkan pihak ketiga sebagai penasihat tanpa wewenang memutuskan. 2. Penyuluh hanya memberi saran sedangkan keputusan tetap di tangan kelompok tani. 3. Jadi cara tersebut disebut mediasi." },
  { q: "Kontraktor dan pemilik proyek yang berselisih soal pembayaran sepakat menunjuk seorang arbiter dan tunduk pada putusannya. Cara penyelesaian tersebut disebut ....", options: ["mediasi", "konsiliasi", "koersi", "arbitrasi"], answer: 3, solution: "1. Arbitrasi adalah penyelesaian lewat pihak ketiga yang keputusannya mengikat. 2. Arbiter yang ditunjuk memutuskan dan kedua pihak wajib tunduk. 3. Jadi cara tersebut disebut arbitrasi." },
  { q: "Sengketa perceraian yang tidak selesai secara musyawarah akhirnya diputus hakim di pengadilan agama. Cara penyelesaian tersebut disebut ....", options: ["ajudikasi", "mediasi", "konsiliasi", "arbitrasi"], answer: 0, solution: "1. Ajudikasi adalah penyelesaian konflik melalui pengadilan. 2. Hakim memutus sengketa secara resmi di pengadilan agama. 3. Jadi cara tersebut disebut ajudikasi." },
  { q: "Pedagang dan pembeli tawar-menawar hingga sepakat pada harga tengah yang tidak merugikan satu pun pihak. Cara penyelesaian tersebut disebut ....", options: ["koersi", "kompromi", "toleransi", "stalemate"], answer: 1, solution: "1. Kompromi adalah penyelesaian dengan kedua pihak saling mengalah sebagian. 2. Harga tengah berarti pedagang dan pembeli sama-sama mengalah. 3. Jadi cara tersebut disebut kompromi." },
  { q: "Dua pihak yang bertikai memiliki kekuatan seimbang sehingga konflik terhenti untuk sementara waktu. Keadaan tersebut disebut ....", options: ["kompromi", "toleransi", "konsiliasi", "stalemate"], answer: 3, solution: "1. Stalemate adalah keadaan saat konflik terhenti karena kekuatan seimbang. 2. Kedua pihak tidak mampu saling mengalahkan sehingga konflik macet sementara. 3. Jadi keadaan tersebut disebut stalemate." },
  { q: "Salah satu syarat terwujudnya integrasi sosial adalah ....", options: ["adanya konsensus terhadap nilai-nilai dasar", "adanya perbedaan kepentingan yang tajam", "adanya dominasi satu kelompok atas lainnya", "adanya isolasi antar kelompok masyarakat"], answer: 0, solution: "1. Integrasi memerlukan kesepakatan bersama tentang nilai yang dijunjung. 2. Konsensus terhadap nilai dasar menyatukan unsur-unsur yang berbeda. 3. Jadi syaratnya adalah adanya konsensus terhadap nilai-nilai dasar." },
  { q: "Perkawinan campur antara dua suku yang berbeda hingga batas-batas budaya asal keduanya melebur merupakan contoh ....", options: ["akulturasi", "asimilasi", "amalgamasi", "diferensiasi"], answer: 1, solution: "1. Asimilasi adalah peleburan dua kebudayaan hingga ciri khas aslinya hilang. 2. Perkawinan campur yang meleburkan batas budaya asal sesuai ciri itu. 3. Jadi contoh tersebut adalah asimilasi." },
  { q: "Musik gamelan yang dipadukan dengan alat musik modern tanpa menghilangkan ciri khas gamelan merupakan contoh ....", options: ["asimilasi", "amalgamasi", "akulturasi", "disintegrasi"], answer: 2, solution: "1. Akulturasi adalah perpaduan budaya tanpa menghilangkan ciri khas budaya asli. 2. Gamelan tetap dikenali meski dipadu musik modern. 3. Jadi contoh tersebut adalah akulturasi." },
  { q: "Perkawinan campur antar kelompok budaya yang berbeda hingga melahirkan kelompok masyarakat dengan kebudayaan baru disebut ....", options: ["asimilasi", "akulturasi", "integrasi", "amalgamasi"], answer: 3, solution: "1. Amalgamasi adalah peleburan kelompok melalui perkawinan campur. 2. Hasilnya adalah kelompok baru dengan kebudayaan perpaduan keduanya. 3. Jadi proses itu disebut amalgamasi." },
  { q: "Umat beragama yang berbeda saling menghormati perayaan hari besar masing-masing. Sikap tersebut merupakan faktor ....", options: ["prasangka", "toleransi", "etnosentrisme", "diskriminasi"], answer: 1, solution: "1. Toleransi adalah sikap menghargai perbedaan. 2. Saling menghormati perayaan agama lain adalah wujud toleransi. 3. Jadi sikap itu merupakan faktor pendorong integrasi berupa toleransi." },
  { q: "Dua kelompok yang bermusuhan justru bersatu ketika menghadapi ancaman dari pihak luar. Faktor pendorong integrasi dalam peristiwa itu adalah ....", options: ["adanya prasangka sosial", "adanya diskriminasi", "adanya musuh bersama", "adanya etnosentrisme"], answer: 2, solution: "1. Musuh bersama dapat menyatukan kelompok-kelompok yang berbeda. 2. Ancaman dari luar membuat dua kelompok bermusuhan melupakan perbedaan. 3. Jadi faktornya adalah adanya musuh bersama." },
  { q: "Penilaian negatif terhadap suku lain tanpa mengenal mereka secara langsung disebut ....", options: ["toleransi", "kesempatan seimbang", "prasangka", "perkawinan campur"], answer: 2, solution: "1. Prasangka adalah penilaian negatif yang belum terbukti kebenarannya. 2. Menilai buruk suku lain tanpa mengenal langsung adalah prasangka. 3. Jadi sikap itu disebut prasangka dan menghambat integrasi." },
  { q: "Anggapan bahwa kebudayaan sendiri paling unggul dibandingkan kebudayaan lain disebut ....", options: ["etnosentrisme", "toleransi", "asimilasi", "akulturasi"], answer: 0, solution: "1. Etnosentrisme adalah sikap menilai budaya lain dengan ukuran budaya sendiri. 2. Menganggap budaya sendiri paling unggul adalah ciri etnosentrisme. 3. Jadi anggapan itu disebut etnosentrisme." },
  { q: "Perlakuan tidak adil terhadap kelompok tertentu, misalnya dalam penerimaan pekerjaan, disebut ....", options: ["integrasi", "diskriminasi", "asimilasi", "akulturasi"], answer: 1, solution: "1. Diskriminasi adalah pembedaan perlakuan yang merugikan kelompok tertentu. 2. Ketidakadilan dalam penerimaan kerja adalah contohnya. 3. Jadi perlakuan itu disebut diskriminasi." },
  { q: "Semboyan yang menjadi simbol pemersatu bangsa Indonesia dalam keberagaman adalah ....", options: ["Sumpah Pemuda", "Bhinneka Tunggal Ika", "UUD 1945", "Pancasila"], answer: 1, solution: "1. Integrasi nasional Indonesia disimbolkan oleh semboyan negara. 2. Bhinneka Tunggal Ika berarti berbeda-beda tetapi tetap satu. 3. Jadi semboyannya adalah Bhinneka Tunggal Ika." },
  { q: "Gerakan sekelompok warga yang ingin memisahkan diri dari NKRI merupakan contoh ....", options: ["integrasi", "reintegrasi", "disintegrasi", "asimilasi"], answer: 2, solution: "1. Disintegrasi adalah terpecahnya kesatuan menjadi bagian-bagian. 2. Gerakan memisahkan diri dari negara merusak keutuhan bangsa. 3. Jadi gerakan itu contoh disintegrasi." },
  { q: "Pandangan yang mengakui dan menghargai keberagaman budaya sebagai kekayaan bangsa disebut ....", options: ["penyeragaman budaya", "penolakan budaya asing", "pengunggulan satu budaya", "pluralisme atau multikulturalisme"], answer: 3, solution: "1. Pluralisme atau multikulturalisme memandang keberagaman secara positif. 2. Mengakui keberagaman sebagai kekayaan adalah inti pandangan itu. 3. Jadi pandangan itu disebut pluralisme atau multikulturalisme." },
  { q: "Menurut Soerjono Soekanto, ciri utama lembaga sosial adalah ....", options: ["memiliki tujuan, tata kelakuan, dan kekekalan", "bersifat sementara dan mudah bubar", "tidak memiliki norma yang mengikat", "hanya terdapat di masyarakat modern"], answer: 0, solution: "1. Soekanto merumuskan lembaga sosial memiliki tujuan yang jelas. 2. Lembaga juga memiliki tata kelakuan sebagai norma dan sifat kekekalan yang bertahan lama. 3. Jadi cirinya adalah memiliki tujuan, tata kelakuan, dan kekekalan." },
  { q: "Perkawinan sebagai lembaga yang tumbuh dan berkembang tanpa direncanakan terlebih dahulu disebut lembaga ....", options: ["enacted", "crescive", "formal", "primer"], answer: 1, solution: "1. Lembaga crescive muncul secara tidak direncanakan dalam masyarakat. 2. Perkawinan tumbuh dari kebiasaan masyarakat, bukan hasil perencanaan. 3. Jadi perkawinan disebut lembaga crescive." },
  { q: "Bank dan sekolah yang sengaja didirikan untuk memenuhi kebutuhan tertentu termasuk lembaga ....", options: ["crescive", "primer", "enacted", "informal"], answer: 2, solution: "1. Lembaga enacted sengaja dibentuk melalui perencanaan. 2. Bank dan sekolah didirikan dengan tujuan dan aturan yang direncanakan. 3. Jadi keduanya termasuk lembaga enacted." },
  { q: "Perbedaan fungsi manifes dan fungsi laten menurut Robert Merton adalah ....", options: ["keduanya selalu disadari", "fungsi laten lebih penting dari manifes", "tidak ada perbedaan keduanya", "fungsi manifes disadari dan diinginkan sedangkan fungsi laten tidak disadari"], answer: 3, solution: "1. Merton membedakan fungsi berdasarkan kesadaran pelakunya. 2. Fungsi manifes adalah akibat yang disadari dan diinginkan, sedangkan laten tidak disadari. 3. Jadi perbedaannya seperti pada pilihan terakhir." },
  { q: "Kegiatan arisan selain untuk menabung juga mempererat silaturahmi antarwarga. Fungsi mempererat silaturahmi tersebut bersifat ....", options: ["manifes", "laten", "primer", "formal"], answer: 1, solution: "1. Fungsi laten adalah akibat yang tidak disadari dan tidak direncanakan. 2. Tujuan arisan adalah menabung, sedangkan silaturahmi adalah akibat sampingan. 3. Jadi fungsi itu bersifat laten." },
  { q: "Perbedaan keluarga nuklir dan keluarga luas terletak pada ....", options: ["keduanya sama saja", "keluarga nuklir lebih besar", "keluarga nuklir terdiri atas ayah, ibu, dan anak sedangkan keluarga luas mencakup kerabat lain", "keluarga luas hanya terdiri atas ayah dan ibu"], answer: 2, solution: "1. Keluarga nuklir adalah keluarga inti yang kecil. 2. Keluarga luas mencakup kakek, nenek, paman, dan kerabat lain. 3. Jadi perbedaannya seperti pada pilihan ketiga." },
  { q: "Penanaman nilai dan norma kepada anak sejak kecil dalam keluarga merupakan fungsi keluarga di bidang ....", options: ["sosialisasi", "reproduksi", "afeksi", "ekonomi"], answer: 0, solution: "1. Sosialisasi adalah proses pewarisan nilai dan norma. 2. Keluarga adalah agen sosialisasi pertama yang menanamkan nilai pada anak. 3. Jadi fungsi itu adalah sosialisasi." },
  { q: "Pelaksanaan salat berjamaah dan upacara keagamaan lainnya menunjukkan fungsi lembaga agama di bidang ....", options: ["doktrin", "ekonomi", "politik", "ritual"], answer: 3, solution: "1. Fungsi ritual berkaitan dengan pelaksanaan ibadah dan upacara. 2. Salat berjamaah dan upacara keagamaan adalah bentuk ibadah ritual. 3. Jadi fungsinya di bidang ritual." },
  { q: "Fungsi utama bank sebagai lembaga ekonomi adalah ....", options: ["menyalurkan aspirasi politik", "menghimpun dan menyalurkan dana masyarakat", "menyelenggarakan pendidikan", "menjaga ketertiban umum"], answer: 1, solution: "1. Lembaga ekonomi mengatur produksi, distribusi, dan konsumsi. 2. Bank berperan menghimpun dana dari masyarakat dan menyalurkannya kembali. 3. Jadi fungsi utamanya adalah menghimpun dan menyalurkan dana masyarakat." },
  { q: "Sebagai lembaga politik, fungsi utama negara adalah ....", options: ["mengatur kegiatan produksi", "menyelenggarakan ibadah", "menjaga ketertiban dan keamanan masyarakat", "menyalurkan dana usaha"], answer: 2, solution: "1. Lembaga politik mengatur penggunaan kekuasaan dalam masyarakat. 2. Negara menggunakan kekuasaannya untuk menjaga ketertiban dan keamanan. 3. Jadi fungsi utamanya adalah menjaga ketertiban dan keamanan masyarakat." },
  { q: "Seorang pencuri dijatuhi hukuman penjara karena melanggar norma yang sanksinya tegas. Norma tersebut adalah ....", options: ["mores atau tata kelakuan", "usage atau cara", "folkways atau kebiasaan", "tidak termasuk norma"], answer: 0, solution: "1. Mores adalah tata kelakuan yang pelanggarannya mendapat sanksi berat. 2. Mencuri melanggar mores sehingga pelakunya dipenjara. 3. Jadi norma itu adalah mores atau tata kelakuan." },
  { q: "Polisi menilang pengendara yang melanggar rambu lalu lintas. Bentuk pengendalian sosial tersebut bersifat ....", options: ["persuasif", "informal", "koersif", "preventif"], answer: 2, solution: "1. Pengendalian koersif menggunakan paksaan atau sanksi tegas. 2. Tilang adalah sanksi paksaan dari aparat resmi. 3. Jadi bentuknya bersifat koersif." },
  { q: "Menurut Lemert, penyimpangan yang dilakukan berulang-ulang hingga pelakunya mendapat cap negatif dari masyarakat disebut penyimpangan ....", options: ["primer", "tersier", "kuarter", "sekunder"], answer: 3, solution: "1. Lemert membedakan penyimpangan primer dan sekunder. 2. Penyimpangan sekunder dilakukan berulang dan pelakunya dicap sebagai penyimpang. 3. Jadi disebut penyimpangan sekunder." },
  { q: "Setelah merumuskan masalah, langkah penelitian yang berupa pengkajian teori dan hasil penelitian terdahulu disebut ....", options: ["merumuskan masalah", "studi pustaka", "menentukan sampel", "menyusun laporan"], answer: 1, solution: "1. Studi pustaka adalah kajian terhadap literatur yang relevan. 2. Langkah ini dilakukan setelah masalah dirumuskan untuk memperkuat landasan teori. 3. Jadi disebut studi pustaka." },
  { q: "Dugaan sementara tentang hubungan antarvariabel yang kebenarannya akan diuji melalui penelitian disebut ....", options: ["kesimpulan akhir", "latar belakang masalah", "dugaan sementara yang akan diuji kebenarannya", "daftar pustaka"], answer: 2, solution: "1. Hipotesis adalah jawaban sementara terhadap rumusan masalah. 2. Kebenarannya harus diuji melalui pengumpulan dan analisis data. 3. Jadi dugaan sementara itu disebut hipotesis." },
  { q: "Perbedaan populasi dan sampel dalam penelitian adalah ....", options: ["populasi adalah keseluruhan objek penelitian sedangkan sampel adalah sebagian yang mewakili", "sampel selalu lebih besar dari populasi", "keduanya memiliki arti yang sama", "populasi hanya digunakan dalam penelitian kualitatif"], answer: 0, solution: "1. Populasi mencakup seluruh objek yang diteliti. 2. Sampel adalah sebagian populasi yang dipilih untuk mewakili keseluruhan. 3. Jadi perbedaannya seperti pada pilihan pertama." },
  { q: "Peneliti memilih responden berdasarkan pertimbangan tertentu karena hanya mereka yang memahami masalah yang diteliti. Teknik sampling tersebut termasuk ....", options: ["probability sampling", "nonprobability sampling", "sensus", "studi kasus"], answer: 1, solution: "1. Nonprobability sampling tidak memberi peluang sama pada setiap anggota populasi. 2. Pemilihan berdasarkan pertimbangan peneliti termasuk nonprobability. 3. Jadi teknik itu termasuk nonprobability sampling." },
  { q: "Peneliti meminta responden awal menunjukkan responden lain yang sesuai kriteria hingga jumlah sampel tercukupi. Teknik sampling tersebut disebut ....", options: ["kuota", "aksidental", "snowball", "sistematis"], answer: 2, solution: "1. Snowball sampling dilakukan secara berantai dari satu responden ke responden lain. 2. Responden awal menunjuk responden berikutnya seperti bola salju yang membesar. 3. Jadi teknik itu disebut snowball." },
  { q: "Peneliti ikut serta dalam kegiatan gotong royong warga sambil mengamati interaksi mereka. Teknik pengumpulan data tersebut adalah observasi ....", options: ["nonpartisipan", "terstruktur", "dokumentasi", "partisipan"], answer: 3, solution: "1. Observasi partisipan menuntut peneliti terlibat langsung dalam kegiatan yang diamati. 2. Peneliti ikut gotong royong sambil mengamati. 3. Jadi tekniknya adalah observasi partisipan." },
  { q: "Alat ukur dikatakan baik jika tepat mengukur apa yang seharusnya diukur. Syarat tersebut disebut ....", options: ["validitas", "reliabilitas", "objektivitas", "efisiensi"], answer: 0, solution: "1. Validitas adalah ketepatan alat ukur terhadap objek yang diukur. 2. Alat yang tepat mengukur apa yang seharusnya diukur berarti valid. 3. Jadi syarat itu disebut validitas." },
  { q: "Peneliti wajib menyamarkan nama responden dalam laporan agar identitasnya tidak diketahui. Kewajiban tersebut termasuk ....", options: ["teknik sampling", "etika penelitian", "analisis data", "rumusan masalah"], answer: 3, solution: "1. Etika penelitian mengatur kewajiban moral peneliti terhadap responden. 2. Menjaga kerahasiaan identitas responden adalah salah satu etika penelitian. 3. Jadi kewajiban itu termasuk etika penelitian." },
  ]
};
